/* ---------------- estado ---------------- */
function loadState() {
  try {
    var raw = localStorage.getItem(LS_KEY);
    if (raw) {
      var s = JSON.parse(raw);
      if (s && s.version === 1) return s;
    }
  } catch (e) {}
  return C.emptyState();
}
function save() {
  try { localStorage.setItem(LS_KEY, JSON.stringify(state)); } catch (e) {
    toast('No se pudo guardar en este teléfono (sin espacio). Libera espacio e inténtalo de nuevo.');
  }
}
function me() { return state.me; }
function myProfile() { return state.me ? state.profiles[state.me] : null; }

