    '<button type="button" class="wrBtn wrCc' + (hasSubs ? ' on' : '') + '" onclick="event.stopPropagation();window.__wrPlayerCC(this)" aria-label="Subtítulos">' + ic('cc', 20) + '</button>' +
    '<button type="button" class="wrBtn wrFull" onclick="event.stopPropagation();window.__wrPlayerFull(this)" aria-label="Pantalla completa">' + ic('expand', 20) + '</button>' +
    '<button type="button" class="wrBtn wrMore" onclick="event.stopPropagation();window.__wrPlayerMenu(this)" aria-label="Más opciones">' + ic('more', 20) + '</button>' +
    '<div class="wrSpeedMenu hidden">' + speeds + '</div>' +
    '</div>';
