/* ---------------- medios (foto/video) ---------------- */
function fileToDataUrl(file, maxDim, quality, cb) {
  var reader = new FileReader();
  reader.onload = function () {
    if (!file.type || file.type.indexOf('image/') !== 0) { cb(reader.result, file.type); return; }
    var img = new Image();
    img.onload = function () {
      var w = img.width, h = img.height;
      var scale = Math.min(1, maxDim / Math.max(w, h));
      if (scale >= 1 && file.size < 1500000) { cb(reader.result, file.type); return; }
      var cv = document.createElement('canvas');
      cv.width = Math.max(1, Math.round(w * scale));
      cv.height = Math.max(1, Math.round(h * scale));
      cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
      cb(cv.toDataURL('image/jpeg', quality || 0.82), 'image/jpeg');
    };
    img.onerror = function () { cb(reader.result, file.type); };
    img.src = reader.result;
  };
  reader.onerror = function () { cb(null); };
  reader.readAsDataURL(file);
}
/* Sube un archivo al puente nativo por partes de 1 MB: en memoria solo
   vive el trozo que se está mandando, nunca el archivo completo, y nada
   pasa por base64 en localStorage. SIN límite de tamaño: el único límite
   es el espacio del teléfono. Si el teléfono se queda sin espacio, el
   puente devuelve ERROR:NO_SPACE y aquí se avisa claro. */
function saveFileChunked(file, cb) {
  var CHUNK = 1024 * 1024;
  var total = file.size || 0;
  var id = null;
  try { id = AndroidBridge.startMediaUpload(file.name || 'archivo'); } catch (e) { id = null; }
  if (!id || (id + '').indexOf('ERROR') === 0) { cb(null, id); return; }
  var offset = 0;
  function finish() {
    var uri = '';
    try { uri = AndroidBridge.finishMediaUpload(id); } catch (e) { uri = 'ERROR'; }
    if (!uri || (uri + '').indexOf('ERROR') === 0) { cb(null, uri); return; }
    cb({ src: uri, type: (file.type || '').indexOf('video/') === 0 ? 'video' : (file.type || '').indexOf('audio/') === 0 ? 'audio' : 'image' });
  }
  function fail(err) {
    try { AndroidBridge.cancelMediaUpload(id); } catch (e) {}
    cb(null, err);
  }
  function next() {
    if (offset >= total) { finish(); return; }
    var slice = file.slice(offset, offset + CHUNK);
    var reader = new FileReader();
    reader.onload = function () {
      var b64 = String(reader.result).split(',')[1] || '';
      var res = 'ERROR';
      try { res = AndroidBridge.appendMediaChunk(id, b64); } catch (e) { res = 'ERROR:' + e; }
      if (!res || (res + '').indexOf('ERROR') === 0) { fail(res); return; }
      offset += slice.size;
      next();
    };
    reader.onerror = function () { fail('ERROR:read'); };
    reader.readAsDataURL(slice);
  }
  next();
}
/* Lee un archivo elegido, SIN límite de tamaño: fotos se achican y quedan
   como dataURL (funciona sin internet); videos y archivos grandes se
   guardan con el puente nativo por partes y se guarda su content:// URI. */
function pickMedia(file, maxDim, cb) {
  if (!file) { cb(null); return; }
  var isAudio = (file.type || '').indexOf('audio/') === 0 || /\.(mp3|m4a|wav|ogg|aac|flac)$/i.test(file.name || '');
  if (isAudio) {
    /* Audio: se guarda por partes con el puente nativo (sin límite), igual
       que los videos. Sin puente, como dataURL. */
    if (window.AndroidBridge && AndroidBridge.startMediaUpload) {
      saveFileChunked(file, function (m, err) {
        if (!m) {
          if (err && (err + '').indexOf('NO_SPACE') >= 0) toast('No hay espacio en el teléfono para guardar ese audio. Libera espacio e inténtalo de nuevo.');
          else toast('No se pudo guardar ese audio.');
          cb(null);
          return;
        }
        cb(m);
      });
      return;
    }
    var ar = new FileReader();
    ar.onload = function () { cb({ src: ar.result, type: 'audio' }); };
    ar.onerror = function () { toast('No se pudo leer ese audio.'); cb(null); };
    ar.readAsDataURL(file);
    return;
  }
  var isVideo = (file.type || '').indexOf('video/') === 0 || /\.(mp4|mov|webm|3gp)$/i.test(file.name || '');
  if (isVideo) {
    if (window.AndroidBridge && AndroidBridge.startMediaUpload) {
      saveFileChunked(file, function (m, err) {
        if (!m) {
          if (err && (err + '').indexOf('NO_SPACE') >= 0) toast('No hay espacio en el teléfono para guardar ese video. Libera espacio e inténtalo de nuevo.');
          else toast('No se pudo guardar ese video.');
          cb(null);
          return;
        }
        cb(m);
      });
      return;
    }
    /* Sin puente nativo (navegador): se guarda como dataURL, también sin
       límite de tamaño; el navegador avisa si no cabe en memoria. */
    var vr = new FileReader();
    vr.onload = function () { cb({ src: vr.result, type: 'video' }); };
    vr.onerror = function () { toast('No se pudo leer ese video.'); cb(null); };
    vr.readAsDataURL(file);
    return;
  }
  fileToDataUrl(file, maxDim || 1024, 0.82, function (dataUrl, type) {
    if (!dataUrl) { toast('No se pudo leer esa foto.'); cb(null); return; }
    if (dataUrl.length > 2500000 && window.AndroidBridge && AndroidBridge.saveMediaFile) {
      try {
        var b64 = dataUrl.split(',')[1] || '';
        var uri = AndroidBridge.saveMediaFile(file.name || 'foto.jpg', b64);
        if (uri && uri.indexOf('ERROR') !== 0) { cb({ src: uri, type: 'image' }); return; }
      } catch (e) {}
    }
    cb({ src: dataUrl, type: 'image' });
  });
}
function mediaPreviewHtml(m) {
  if (!m) return '';
  var inner = m.type === 'video'
    ? wrPlayerHtml('<video src="' + m.src + '" playsinline></video>')
    : '<img src="' + m.src + '" alt="Vista previa">';
  return inner + '<button class="rm" type="button" onclick="window.__wrClearMedia()">✕</button>';
}
