    cv.width = 192; cv.height = 192;
    var ctx = cv.getContext('2d');
    ctx.fillStyle = WordRedGames.tileColor(id);
    ctx.fillRect(0, 0, 192, 192);
    ctx.font = 'bold 110px Arial';
