    var res = AndroidBridge.pinGameShortcut(id, info.name, icon.replace(/^data:image\/png;base64,/, ''));
    if (res === 'UNSUPPORTED') toast('Este teléfono no permite anclar accesos directos en el escritorio.');
    else if (res === 'ERROR') toast('No se pudo instalar ' + info.name + ' en el escritorio.');
    else toast('Confirma en el teléfono para poner ' + info.name + ' en el escritorio.');
