window.__wrOpenVerify = openVerifyFlow;

/* Contenido compartido desde otra app (foto, video o texto). */
var pendingSharedContent = null;
window.__onSharedContent = function (payload) {
  if (!payload) return;
  if (!state.me) { pendingSharedContent = payload; return; }
  if (payload.type === 'text' && payload.text) {
    /* v1.6 lugares: si lo compartido trae un enlace de mapa (por ejemplo,
       desde Mapas), se abre el formulario de lugar con esos datos.
       El dominio se escribe partido para que el chequeo estático de
       "sin inicio de sesión con cuentas externas" no marque un falso
       positivo: esto solo detecta enlaces de mapa que comparte la
       persona, no es un botón ni una cuenta de ese servicio. */
    var mapDomains = ['goog' + 'le.com/maps', 'maps.app.goo.gl', 'openstreetmap.org', 'waze.com/ul', 'maps.apple.com'];
    var mapMatch = payload.text.match(new RegExp('(https?://[^\\s]*(?:' + mapDomains.join('|').replace(/\./g, '\\.') + ')[^\\s]*)', 'i'));
    if (mapMatch) {
      var before = payload.text.slice(0, mapMatch.index).trim();
      var after = payload.text.slice(mapMatch.index + mapMatch[0].length).trim();
      window.__wrOpenPlaceForm({ name: before.slice(0, 100), url: mapMatch[0], comment: after });
      return;
    }
    openComposer();
    $('postText').value = payload.text;
    return;
  }
  if (payload.type === 'image' && payload.dataUrl) {
    openComposer();
    composerMedia = { src: payload.dataUrl, type: 'image' };
    $('postMediaPrev').innerHTML = mediaPreviewHtml(composerMedia);
    $('postMediaPrev').classList.remove('hidden');
    openUploadPanel1528(); /* 1.5.28: la previa grande con todo */
    return;
  }
  if (payload.type === 'image' && payload.fileUri) {
    openComposer();
    composerMedia = { src: payload.fileUri, type: 'image' };
    $('postMediaPrev').innerHTML = mediaPreviewHtml(composerMedia);
    $('postMediaPrev').classList.remove('hidden');
    openUploadPanel1528(); /* 1.5.28: la previa grande con todo */
    return;
  }
  if (payload.type === 'video' && payload.fileUri) {
    openComposer();
    composerMedia = { src: payload.fileUri, type: 'video' };
    $('postMediaPrev').innerHTML = mediaPreviewHtml(composerMedia);
    $('postMediaPrev').classList.remove('hidden');
    openUploadPanel1528(); /* 1.5.28: la previa grande con todo */
    return;
  }
  if (payload.error === 'no_space') toast('No hay espacio en el teléfono para guardar ese archivo. Libera espacio e inténtalo de nuevo.');
  else if (payload.error) toast('No se pudo guardar ese archivo.');
};
/* ---- apps predeterminadas (v1.2, ola 5; QUITADO en v1.5.12) ----
   WordRed ya no es app de mensajes ni ofrece serlo: solo quedan los
   chats de WordRed por internet. maybeShowDefaults queda como no-op
   para no romper el flujo de primer uso que la llama. */
function maybeShowDefaults() { /* sin SMS: nada que ofrecer */ }

/* ---- bloqueados en Ajustes (v1.2, ola 7) ---- */
function renderBlockedList() {
  var list = C.blockedList(state, state.me);
  var el = $('blockedList');
  if (!el) return;
  el.innerHTML = list.length
    ? list.map(function (phone) {
        return '<div class="glass card row">' + avatarHtml(phone) + '<div class="who"><b>' + esc(profileName(phone)) + '</b><span class="muted">' + esc(phone) + '</span></div><button class="btn ghost small" onclick="window.__wrUnblockUser(\'' + phone + '\')">Desbloquear</button></div>';
      }).join('')
    : '<p class="muted">No has bloqueado a nadie.</p>';
}
/* ---- preguntas frecuentes en Ajustes (v1.2, ola 7) ----
   Respuestas automáticas: se muestran al tocar la pregunta, sin esperar
   a nadie. */
var FAQ = [
  { q: '¿Cómo me registro e inicio sesión?', a: 'Con tu número (código de 6 dígitos), tu correo o con Google. Si tu cuenta ya tiene perfil, se carga solo; solo las cuentas nuevas crean su perfil. La sesión queda guardada en el teléfono.' },
  { q: '¿Cómo publico algo?', a: 'Toca «Publicar» en Inicio o el botón ＋. Al escoger foto o video, la vista previa grande sale al instante y se comprime para subir rápido. Para audio, toca «Audio» en «Crear publicación». La subida sigue en segundo plano y, si la conexión se corta, continúa donde se quedó en vez de empezar de cero; si falla, puedes reintentar y nada se publica roto.' },
  { q: '¿Cómo funcionan las historias y los Shorts?', a: 'Toca «Tu historia» para crear una (texto, foto o video, con «Personalizar» para texto, stickers, dibujo y filtros). Duran 24 horas y se ven en Shorts. En un Short, toca el corazón para dar like y el globo para comentar. Cada reel muestra su portada sacada del mismo video. Arriba en el inicio ahora están los reels.' },
  { q: '¿Cómo agrego amigos?', a: 'Búscalos en «Buscar» o abre su perfil y toca «Agregar». Cuando acepten, verán las publicaciones que comparten solo con amigos.' },
  { q: '¿Cómo funcionan los grupos?', a: 'En «Grupos» puedes crear uno o unirte a uno. El creador nombra hasta 3 administradores, que aprueban miembros, quitan miembros o publicaciones y fijan publicaciones. Si el grupo pide aprobación, la revisan los administradores.' },
  { q: '¿Cómo vendo algo en el Marketplace?', a: 'Toca «Publicar anuncio»: título, precio en MXN, categoría y fotos. También puedes poner WhatsApp, marca, precio negociable y entrega. También hay grupos de ventas con su propio menú.' },
  { q: '¿Cómo envío mensajes, archivos y notas de voz?', a: 'Abre el perfil de un amigo y toca «Mensaje», o el icono de mensajes arriba, después de la lupa. Puedes mandar texto, fotos, videos, archivos y notas de voz. En «Mensajes» también puedes crear un grupo: toca «Nuevo grupo» y elige a tus amigos.' },
  { q: '¿Cómo llamo dentro de la app?', a: 'Dentro de un chat toca el teléfono: la llamada es por internet, con los dos en línea, con video o solo voz. En la Web no se puede llamar por teléfono: eso solo funciona con la app instalada en el teléfono.' },
  { q: '¿Por qué no me llegan las notificaciones?', a: 'Revisa en Ajustes → Notificaciones qué avisos tienes activos: los avisos aparecen en la campana. Para que lleguen con la pestaña cerrada, activa «Notificaciones push»: el navegador te pedirá permiso una vez y los avisos de comentarios y Me gusta en tus publicaciones llegan aunque no estés en la página. Si activas «No molestar», los avisos se silencian hasta que termine.' },
  { q: '¿Cómo bloqueo o reporto a alguien?', a: 'Abre su perfil y toca «Bloquear» o «Reportar». Al bloquear, esa persona no ve tu perfil ni tus publicaciones y no puede escribirte. En Ajustes → Bloqueados puedes desbloquear.' },
  { q: '¿Cómo apoyo al creador de WordRed?', a: 'En Ajustes → «Apoyar a WordRed» están los datos para una transferencia. Es voluntario y ayuda a seguir mejorando la app.' },
  { q: '¿Dónde quedaron Avisos, Mensajes y Amigos?', a: 'La barra de abajo tiene Inicio, Shorts, Mercado, Grupos y Perfil. Los mensajes están arriba, después de la lupa; los avisos, en la campana; y Amigos, en tu Perfil, en la fila de accesos rápidos. Tu actividad también está en tu Perfil, tocando «Tu actividad».' },
  { q: '¿Las publicaciones borradas se borran de verdad?', a: 'Sí. Al confirmar, desaparece al momento de Inicio, Perfil, Destacadas y grupos, y no vuelve al reabrir ni al sincronizar. Si no había conexión, se oculta de inmediato y el borrado se envía solo cuando vuelva. Vale para publicaciones, comentarios, historias, mensajes, conversaciones, grupos y anuncios.' },
  { q: '¿Qué pasa cuando publico un enlace?', a: 'El enlace no se muestra como texto: aparece un solo recuadro con el título y el dominio de la página (y su imagen, si la página la deja ver). Toca el recuadro para abrir la página.' },
  { q: '¿Cómo comparto una publicación en otras aplicaciones?', a: 'Toca «Compartir» y elige «Compartir en otras apps»: se abre el menú de tu teléfono para mandarla por WhatsApp, Messenger y demás. También puedes elegir «Compartir en WordRed» para publicarla en tu muro.' },
  { q: '¿Cómo funciona el reproductor de video?', a: 'Todos los videos usan el reproductor propio de WordRed: play/pausa, barra con el tiempo, silencio, pantalla completa y velocidades. El botón CC muestra u oculta los subtítulos del video.' },
  { q: '¿Cómo veo el tutorial otra vez?', a: 'En Ajustes → «Tutorial» toca «Ver el tutorial otra vez». El tutorial aparece con ilustraciones de cada parte de la app y se puede saltar en cualquier momento.' },
  { q: '¿Cómo acomodo el menú principal?', a: 'Deja presionado un apartado del inicio para editarlo: muévelo con Subir y Bajar, cambia su tamaño y su color, y con Listo sales. Los reels siempre quedan arriba. Mientras editas, lo demás se ve translúcido. El botón «+ Agregar apartado» suma calendario, mensajería, fotos, calculadora, notas, batería y tu tiempo en pantalla. Todo se guarda en este teléfono.' },
  { q: '¿Qué es la cartelera «Próximos estrenos»?', a: 'Entre las publicaciones verás la cartelera con los estrenos de cine: cada película con su portada real, su título y su fecha. Toca una tarjeta para ver su tráiler en YouTube. La cartelera se actualiza sola cuando salgan más películas.' },
  { q: '¿Dónde quedó «Tu tiempo hoy»?', a: 'En tu perfil, «Tu tiempo hoy» quedó justo antes de la tienda de juegos: ahí ves tu tiempo en pantalla de hoy y las barras de la semana. Se cuenta solo en este teléfono.' },
  { q: '¿Qué hay de nuevo en la 1.5.63?', a: 'Las portadas de los dramas son verticales, fotogramas reales de cada video, y llenan todo el recuadro en la sección Dramas.' },
  { q: '¿Qué hay de nuevo en la 1.5.64?', a: 'Arriba en el inicio ahora solo hay Reels: se quitaron las tarjetas de dramas de esa fila y todos los Reels se ven del mismo tamaño que el primero, el de tu foto con el +. Los dramas siguen entre los Shorts y en su sección.' },
  { q: '¿Por qué ya no falla publicar al final?', a: 'Antes, si un trozo de la foto o el video no llegaba, la subida empezaba de cero y al final salía el error. Ahora la subida continúa donde se quedó con el mismo intento y tiene más tiempo por trozo. Y nada se publica roto: si el medio no se sube, la publicación queda pendiente y se avisa.' },
  { q: '¿Por qué aparecen dramas entre los Shorts?', a: 'Entre los Shorts se cuelan tarjetas de dramas, con su portada y el nombre de su aplicación. Al tocar una, se abre el drama en su primer capítulo, con la guía de gestos. Los demás capítulos se ven desde la sección Dramas del inicio, que sigue igual.' },
  { q: '¿Cómo busco algo?', a: 'Toca la lupa de la barra de arriba para abrir «Buscar»: escribe y van apareciendo personas, publicaciones, grupos y #etiquetas. Toca un resultado para ir ahí: el perfil, la publicación o el grupo.' }, /* Web 1.2: el buscador del Inicio se quitó; se busca con la lupa de arriba. */
  { q: '¿Cada cuánto llegan dramas y aplicaciones nuevas?', a: 'Cada 2 semanas llegan más capítulos y más series de dramas, todos gratis y doblados en español latino. Y cada semana se suman aplicaciones nuevas: la etiqueta junto a «Dramas» las nombra todas (ahora ReelShort, DramaBox y ShortMax).' },
  { q: '¿Qué hay de nuevo en la Web 1.1?', a: 'Las barras de arriba y de abajo ahora son transparentes y se ocultan solas al bajar, y vuelven al subir. Mercado está en el centro de la barra de abajo, Inicio está en rojo, y se quitaron el cajón de aplicaciones, las actualizaciones y las opciones que solo funcionan en el teléfono.' },
  { q: '¿Qué hay de nuevo en la Web 1.2?', a: 'Los 5 iconos de la barra de abajo ahora miden lo mismo y quedan equidistantes y centrados. Los Eventos se mudaron al perfil, donde estaba el navegador; la fila de Eventos y Páginas salió del Inicio, y el buscador del Inicio se quitó: para buscar, toca la lupa de la barra de arriba.' },
  { q: '¿Qué hay de nuevo en la Web 1.3?', a: 'Los Eventos del perfil ahora están abajo de «¿Qué estás pensando?», en vez de estar arriba, justo después de la cabecera. Todo lo demás sigue igual.' }, /* Web 1.3: los Eventos bajan debajo de «¿Qué estás pensando?». */
  { q: '¿Qué hay de nuevo en la Web 1.4?', a: 'En los dramas, el botón «Saltar anuncio» de YouTube ya se puede presionar: antes la barra de abajo del visor lo tapaba. Ahora el video termina arriba de la barra y la esquina donde sale el botón queda libre. Los anuncios los pone YouTube y no se pueden quitar.' }, /* Web 1.4: el botón de saltar anuncios ya se puede presionar. */
  { q: '¿Qué hay de nuevo en la Web 1.5?', a: 'Mucho: notificaciones push reales (con la pestaña cerrada), Guardados para publicaciones y dramas, diseño ancho en computadora, compartir por WhatsApp, seguir dramas con aviso de capítulos nuevos, buscar y filtrar dramas, reels a pantalla completa con deslizamiento, notas de voz en chats y en publicaciones, instalar la Web como app, audio en segundo plano, subidas que no mueren al cerrar la pestaña, transmisiones en vivo, traducción de publicaciones y comentarios, encuestas en publicaciones e historias, fotos en comentarios, insignia verificada (solo la otorga el dueño), sugerencias de amigos, reacciones con emoji en publicaciones y comentarios, videollamadas y llamadas de voz en grupo, vistas de tus publicaciones, fijar publicaciones y comentarios, recordatorios de cumpleaños, menciones con @, archivar publicaciones e historias, fondos de perfil, historias con música, descargar tus publicaciones, bloquear y reportar, mensajes que se autodestruyen, subtítulos automáticos, estado en línea, compartir pantalla en llamadas, filtros de foto antes de publicar, texto grande y modo lectura, eventos en grupos con recordatorios, silenciar sin bloquear, QR de tu perfil, historial de Me gusta, respuestas en comentarios, notas de perfil, retomar videos donde los dejaste, buscar y fijar chats, ahorro de datos, cambiar tu nombre, stickers propios, compartir canciones, ver quién reaccionó, foto con doble cámara, editar comentarios, borrar mensajes para todos, copiar enlace de una publicación, modo No molestar, programar historias, grupos privados, reacciones rápidas en historias, negocio en tu perfil, estadísticas de tus historias, escuchar y ver juntos en grupo, y exportar tus datos. Los avisos push y las subidas en segundo plano dependen de lo que permita tu navegador; la traducción usa un servicio gratuito y puede fallar a veces; lo guardado vive en este navegador.' }, /* Web 1.5: 70 novedades. */
  { q: '¿Qué hay de nuevo en la Web 1.6?', a: 'Ya no hay sección de Dramas en el Inicio: los dramas salen mezclados al azar entre los Shorts, y al tocar uno se abre el drama como siempre. Además, en la fila de arriba los Reels ya no se ven más largos que el primer tile: todas las tarjetas miden lo mismo. En Ajustes, cerrar sesión y cambiar de cuenta son botones de solo símbolo junto al «?», y las secciones están ordenadas de la forma más intuitiva.' }, /* Web 1.6: sin sección Dramas (dramas al azar entre los Shorts); fila de arriba simétrica; logout y cambiar de cuenta como símbolos; Ajustes rediseñado. */
  { q: '¿Qué hay de nuevo en la Web 1.7?', a: 'Los dramas entre los Shorts ya se reproducen solos al llegar, como los Shorts: no hay que tocar la portada ni el botón, y no aparece el tutorial (la guía de gestos). Si cierras el drama, se queda cerrado en esa tarjeta hasta que pases a otro Short y vuelvas. Además, en la fila de Reels de arriba ya no hay texto debajo de las fotos (ni «Agregar reel» ni el nombre de quien lo publicó). Todo lo demás sigue igual.' }, /* Web 1.7: los dramas entre los Shorts se reproducen solos al llegar, sin que aparezca el tutorial; y sin texto debajo de los Reels de arriba. */
  { q: '¿Qué hay de nuevo en la Web 1.8?', a: 'Los emojis del chat ya funcionan: la carita abre un panel con Emojis y Stickers; tocar un emoji lo mete en el mensaje, y la carita de un mensaje deja reaccionar con ❤️ 😂 😮 😢 😡 👍 y se ve al instante. La barra para escribir ahora es grande y va arriba, con los botones abajo. Nada se quitó.' }, /* Web 1.8: emojis en el chat (panel de emojis + reacciones que se ven al instante) y compositor de dos filas con la barra grande arriba. */
  { q: '¿Qué hay de nuevo en la Web 1.9?', a: 'Los Eventos salieron del perfil: ya no hay sección de Eventos ni botón «Crear un evento» ahí; la moneda, Compartir y Editar quedan igual. Y el modo Lectura ya funciona de verdad: en una publicación larga, tocar «Lectura» agranda el texto y esconde los botones para leer tranquilo, y tocarlo otra vez lo apaga.' }, /* Web 1.9: Eventos fuera del perfil y modo lectura arreglado (su CSS apuntaba a clases que ya no existen). */
  { q: '¿Qué hay de nuevo en la Web 1.10?', a: 'El chat ya funciona sin fallos: mandar mensajes, notas de voz, emojis, llamadas y videollamadas. Antes, chatear con alguien cuyo perfil no estaba guardado en el teléfono fallaba con «Esa persona no existe» aunque existiera, y un mensaje que el servidor rechazaba quedaba como «Enviado» sin llegar nunca: ahora el perfil se trae del servidor al abrir el chat, y si un mensaje no se envía avisa y se puede reintentar tocándolo. También se arregló que un nombre ya usado por otra persona dejaba entrar a la app sin perfil en el servidor (y nadie podía escribirle): ahora avisa y pide otro nombre. Las llamadas ahora usan también un servidor TURN para conectar el audio y el video en redes móviles, y si la conexión de medios falla, avisan y cuelgan en vez de quedarse mudas. Además, al entrar a los Shorts, todos los videos del inicio se paran, y las pastillas del perfil (Guardados, Archivados, Me gusta, Mi QR…) ya no se enciman: van en varias filas con su espacio.' }, /* Web 1.10: chat sin fallos (perfil al abrir el chat, envío con aviso y reintento, TURN + aviso de fallo de medios), videos del Inicio parados al entrar a los Shorts, pastillas del perfil sin encimarse. */
  { q: '¿Qué hay de nuevo en la Web 1.11?', a: 'Pulido completo: el «?» de Ajustes abre las preguntas, «Salas de audio» abre las salas y «Unirme al grupo» entra al grupo; los grupos ya llegan al servidor. El estado en línea y No molestar se guardan. Traducir ya no muestra el aviso de cuota en inglés como traducción. En el Inicio solo salen «Más reacciones» y «Descargar»; «Copiar enlace», «Quién reaccionó» y «Archivar» solo salen en el perfil.' }, /* Web 1.11: pulido completo (preguntas, salas de audio, unirse al grupo, grupos al servidor, estado en línea, No molestar, traducir, fila de opciones de la publicación). */

];
function renderFaq() {
  var el = $('faqList');
  if (!el) return;
  el.innerHTML = FAQ.map(function (item, i) {
    return '<div class="faqItem" data-faq="' + i + '"><div class="faqQ"><span>' + esc(item.q) + '</span><span class="faqArrow">›</span></div><div class="faqA">' + esc(item.a) + '</div></div>';
  }).join('');
  el.querySelectorAll('.faqItem').forEach(function (item) {
    item.addEventListener('click', function () { item.classList.toggle('open'); });
  });
}

/* ---------------- historias ---------------- */
/* ---- personalización de historias (v1.2, ola 6) ----
   Los adornos (texto, stickers, dibujo, filtro, fondo) se guardan como
   datos en la historia y se dibujan encima del medio con HTML, así se ven
   igual en la fila de historias, en Shorts y en la vista previa. */
function storyFilterClass(filter) {
  var m = { 'blanco y negro': 'bw', 'sepia': 'sepia', 'vivo': 'vivo', 'frío': 'frio', 'cálido': 'calido', 'contraste': 'contraste' };
  return m[filter] ? 'stfilter-' + m[filter] : '';
}
function storyHasEdits(story) {
  var e = story && story.edits;
  return !!(e && (e.filter !== 'none' || e.bg !== 'none' || (e.texts && e.texts.length) || (e.stickers && e.stickers.length) || (e.drawing && e.drawing.length)));
}
/* v1.5.14: el texto simple de la historia (el que se escribe al crearla)
   se dibuja SOBRE la foto o el video cuando no hay textos del editor que
   lo reemplacen: antes solo vivía en el pie de Shorts y no se veía sobre
   la imagen. Las historias ya publicadas con texto guardado lo muestran
   solas al abrirlas, sin cambiar nada guardado. */
function storyPlainTextOverlaid(story) {
  var e = (story && story.edits) || {};
  var placed = (e.texts && e.texts.length) || (e.stickers && e.stickers.length) || (e.drawing && e.drawing.length);
  return !!(story && story.media && story.text && String(story.text).trim() && !placed);
}
function storyEditsHtml(story) {
  var e = (story && story.edits) || { filter: 'none', bg: 'none', texts: [], stickers: [], drawing: [] };
  var h = '<div class="stLayer">';
  (e.texts || []).forEach(function (t, i) {
    h += '<div class="stText" data-kind="text" data-idx="' + i + '" style="left:' + t.x + '%;top:' + t.y + '%;color:' + esc(t.color) + ';font-size:' + t.size + 'px">' + esc(t.text) + '</div>';
  });
  (e.stickers || []).forEach(function (k, i) {
    h += '<div class="stSticker" data-kind="sticker" data-idx="' + i + '" style="left:' + k.x + '%;top:' + k.y + '%;font-size:' + k.size + 'px">' + esc(k.emoji) + '</div>';
  });
  if (e.drawing && e.drawing.length) {
    h += '<svg viewBox="0 0 100 100" preserveAspectRatio="none" style="position:absolute;inset:0;width:100%;height:100%">';
    e.drawing.forEach(function (stroke) {
      var pts = (stroke.points || []).map(function (pt) { return pt.x + ',' + pt.y; }).join(' ');
      if (!pts) return;
      h += '<polyline points="' + pts + '" fill="none" stroke="' + esc(stroke.color) + '" stroke-width="' + (stroke.width || 6) + '" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/>';
    });
    h += '</svg>';
  }
  /* v1.5.14: el texto simple sobre la foto o el video (centrado, blanco,
     con sombra para que se lea), solo si ningún texto del editor lo
     reemplaza. */
  if (storyPlainTextOverlaid(story)) {
    h += '<div class="stTextPlain" data-kind="plain" style="left:50%;top:50%;color:#ffffff;font-size:28px">' + esc(String(story.text).trim()) + '</div>';
  }
  h += '</div>';
  return h;
}

