    edits: storyEdit.edits,
    song: storyEdit.song,
    videoEdits: storyEdit.videoEdits || null,
    /* 1.5.26: lo elegido en el creador (encuesta, enlace, audiencia, fondo,
       portada de nota de voz) también viaja cuando se publica desde el editor. */
    poll: (storyPollQ.trim() && storyPollOpts[0].trim() && storyPollOpts[1].trim()) ? { question: storyPollQ.trim(), options: [storyPollOpts[0].trim(), storyPollOpts[1].trim()] } : undefined,
    link: storyLink.trim() || undefined,
    audience: storyAudience === 'close' ? 'close' : undefined,
    backgroundColor: storyBgColor || undefined,
