    var done = false;
    var finish = function () { if (done) return; done = true; try { window.URL.revokeObjectURL(url); } catch (e) {} try { if (v.parentNode) v.parentNode.removeChild(v); } catch (e) {} };
    var timer = setTimeout(finish, 3000);
    v.addEventListener('loadedmetadata', function () { clearTimeout(timer); var w = v.videoWidth || 0, h = v.videoHeight || 0; if (w && h) entry.orientation = (h > w) ? 'vertical' : 'horizontal'; finish(); });
    v.addEventListener('error', function () { clearTimeout(timer); finish(); });
