/* Negrita y cursiva: envuelven el texto seleccionado con ** o * (v1.2). */
function wrapSelection(prefix, suffix) {
  var ta = $('postText');
  var start = ta.selectionStart || 0;
  var end = ta.selectionEnd || 0;
  var val = ta.value;
  var sel = val.slice(start, end);
  var wrapped = sel ? prefix + sel + suffix : prefix + 'texto' + suffix;
  ta.value = val.slice(0, start) + wrapped + val.slice(end);
  ta.focus();
  ta.selectionStart = start + prefix.length;
  ta.selectionEnd = start + prefix.length + (sel ? sel.length : 5);
}
