  var list = groupsTab === 'mine' ? mine : state.groups.filter(function (g) { return g.members.indexOf(state.me) < 0; });
  if (!list.length) {
    el.innerHTML = '<div class="empty"><div class="big">' + ic('users', 34) + '</div><p>' + (groupsTab === 'mine' ? 'No estás en ningún grupo todavía.' : 'No hay grupos nuevos para descubrir.') + '</p></div>';
    return;
  }
  el.innerHTML = list.map(function (g) {
    var isMember = g.members.indexOf(state.me) >= 0;
    return '<div class="glass card" onclick="window.__wrOpenGroup(\'' + g.id + '\')">' +
      '<div class="groupcover"><b>' + esc(g.name) + '</b></div>' +
      '<div class="row"><div class="who"><span class="muted">' + esc(g.desc || 'Sin descripción.') + '</span><div class="tiny">' + g.members.length + (g.members.length === 1 ? ' miembro' : ' miembros') + '</div></div>' +
      (isMember ? '<span class="tiny">Miembro ✓</span>' : '<button class="btn small" onclick="event.stopPropagation();window.__wrJoinGroup(\'' + g.id + '\')">Unirme</button>') +
      '</div></div>';
  }).join('');
