    saveFileChunked(file, function (res) {
      if (res && res.src) { cb({ name: file.name, size: file.size, mime: file.type || 'application/octet-stream', uri: res.src }); return; }
      toast('No se pudo guardar ese archivo.');
      cb(null);
    });
