/* ---- mensajes de voz (v1.2): grabar con el puente nativo (MediaRecorder)
   o con el MediaRecorder del WebView; sin límite de tamaño. ---- */
function voiceRecShow() { $('voiceRecBar').classList.remove('hidden'); $('voiceRecTime').textContent = '0:00'; }
function voiceRecHide() { $('voiceRecBar').classList.add('hidden'); }
function voiceRecTick() { $('voiceRecTime').textContent = C.formatDuration(Date.now() - voiceRec.startTime); }
function startVoiceRecord() {
  if (voiceRec.active || (!openChatPhone && !voiceRecForStory)) return; /* 1.5.26: sin chat abierto solo se graba para una historia. */
  if (window.AndroidBridge && AndroidBridge.startVoiceRecording) {
    try {
      var r = AndroidBridge.startVoiceRecording();
      if (String(r || '').indexOf('ERROR') === 0) { toast('No se pudo empezar a grabar: ' + String(r).slice(6)); return; }
      voiceRec.active = true; voiceRec.native = true; voiceRec.startTime = Date.now();
      voiceRecShow();
      voiceRec.timer = setInterval(voiceRecTick, 500);
      return;
    } catch (e) {}
  }
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { toast('Este teléfono no permite grabar audio desde la app.'); return; }
  navigator.mediaDevices.getUserMedia({ audio: true }).then(function (stream) {
    var mr = null;
    try { mr = new MediaRecorder(stream); } catch (e) { toast('No se pudo grabar audio en este teléfono.'); stream.getTracks().forEach(function (t) { t.stop(); }); return; }
    voiceRec.active = true; voiceRec.native = false; voiceRec.startTime = Date.now();
    voiceRec.chunks = []; voiceRec.mediaRecorder = mr; voiceRec.stream = stream;
    mr.ondataavailable = function (e) { if (e.data && e.data.size) voiceRec.chunks.push(e.data); };
    mr.onstop = function () {
      stream.getTracks().forEach(function (t) { t.stop(); });
      var blob = new Blob(voiceRec.chunks, { type: mr.mimeType || 'audio/webm' });
      finishVoiceRecordWeb(blob, Date.now() - voiceRec.startTime);
    };
    mr.start();
    voiceRecShow();
    voiceRec.timer = setInterval(voiceRecTick, 500);
  }).catch(function () { toast('Sin permiso de micrófono no se puede grabar el mensaje de voz. Actívalo en Ajustes.'); });
}
function stopVoiceRecord(send) {
  if (!voiceRec.active) return;
  if (!send) voiceRecForStory = false; /* 1.5.26: al cancelar no queda la marca para la historia. */
  clearInterval(voiceRec.timer);
  voiceRec.active = false;
  voiceRecHide();
  if (voiceRec.native) {
    try { if (send) AndroidBridge.stopVoiceRecording(); else AndroidBridge.cancelVoiceRecording(); } catch (e) {}
    return; /* El puente avisa con __onVoiceRecorded(uri, durationMs). */
  }
  if (voiceRec.mediaRecorder && voiceRec.mediaRecorder.state !== 'inactive') {
    voiceRec.sendOnStop = !!send;
    voiceRec.mediaRecorder.stop();
  }
}
function finishVoiceRecordWeb(blob, dur) {
  if (!voiceRec.sendOnStop) { voiceRecForStory = false; return; }
  /* 1.5.26: si se grabó para una historia, la nota va al creador de
     historias, no al chat. */
  if (voiceRecForStory) {
    voiceRecForStory = false;
    var file = new File([blob], 'voz_historia_' + Date.now() + '.webm', { type: blob.type || 'audio/webm' });
    if (window.AndroidBridge && AndroidBridge.startMediaUpload) {
      saveFileChunked(file, function (res) {
        if (res && res.src) storyVoiceFromChat1526(res.src, dur);
        else toast('No se pudo guardar la nota de voz para la historia.');
      });
    } else if (blob.size < 4000000) {
      var reader = new FileReader();
      reader.onload = function () { storyVoiceFromChat1526(reader.result, dur); };
      reader.readAsDataURL(blob);
    } else toast('La nota de voz es muy larga para este modo.');
    return;
  }
  var file = new File([blob], 'voz_' + Date.now() + '.webm', { type: blob.type || 'audio/webm' });
  if (window.AndroidBridge && AndroidBridge.startMediaUpload) {
    saveFileChunked(file, function (res) {
      if (res && res.src) sendVoiceMessage(res.src, dur, blob.size, blob.type || 'audio/webm');
      else toast('No se pudo guardar el mensaje de voz.');
    });
  } else if (blob.size < 4000000) {
    var reader = new FileReader();
    reader.onload = function () { sendVoiceMessage(reader.result, dur, blob.size, blob.type || 'audio/webm'); };
    reader.readAsDataURL(blob);
  } else toast('El mensaje de voz es muy largo para este modo.');
}
window.__onVoiceRecorded = function (uri, durationMs) {
  if (!uri) { voiceRecForStory = false; toast('No se pudo guardar el mensaje de voz.'); return; }
  /* 1.5.26: si se grabó para una historia, la nota va al creador de
     historias, no al chat. */
  if (voiceRecForStory) { voiceRecForStory = false; storyVoiceFromChat1526(uri, Number(durationMs) || 0); return; }
  sendVoiceMessage(uri, Number(durationMs) || 0, 0, 'audio/mpeg');
};
async function sendVoiceMessage(uri, durationMs, size, mime) {
  if (!openChatPhone) return;
  /* Web 1.10: igual que al escribir (ver sendChat): sin el perfil del
     destinatario en este teléfono el envío se rechaza en local. */
  if (!state.profiles[openChatPhone]) {
    var ensuredV1562 = await ensureChatProfile1562(openChatPhone);
    if (ensuredV1562 === false) { toast('Esa persona no existe en WordRed.'); return; }
    if (ensuredV1562 === 'offline') state.profiles[openChatPhone] = { phone: openChatPhone, name: openChatPhone, createdAt: Date.now() };
  }
  /* v1.4: el audio se sube al servidor antes de enviar, para que el
     otro lo escuche en vivo desde la URL. */
  var voiceUri = uri;
  if (uri && isLocalMediaSrc(uri)) {
    var vurl = null;
    try {
      if (String(uri).indexOf('data:') === 0) {
        var vp = String(uri).split(',');
        vurl = await C.uploadMediaBase64(state, vp[1] || '', (vp[0].match(/data:([^;]+)/) || [])[1] || mime || 'audio/mpeg', 'voz.m4a', function (p) { showUploadProgress(p, 'Subiendo voz…'); }, { onStatus: mediaUploadStatus1546 });
      } else {
        vurl = await uploadContentUriToServer(uri, mime || 'audio/mpeg', 'voz.m4a', function (p) { showUploadProgress(p, 'Subiendo voz…'); }, { onStatus: mediaUploadStatus1546 });
      }
    } catch (e) { vurl = null; }
    hideUploadProgress();
    if (vurl) voiceUri = vurl;
  }
  var r = C.sendMessage(state, state.me, openChatPhone, '', '', '', null, { uri: voiceUri, duration: durationMs, size: size, mime: mime });
  if (!r.ok) { toast(r.error); return; }
  save();
  justSentMessageId = r.message.id;
  renderChatMsgs();
  /* v1.4: lo que quedó en local se sube solo al reconectar. Web 1.10:
     si la voz sigue en local (la subida falló), el envío va detrás de
     su subida (ver pushChatMessageToServer1562): el otro la recibe
     con la URL pública, no con la data: larguísima. */
  pushChatMessageToServer1562(r.message, openChatPhone, false);
  showSuccess('Mensaje de voz enviado.');
}
