/* ---------------- notificaciones ---------------- */
function renderNotifs() {
  /* 1.5.43: en la campana no aparece nada de la cuenta de ejemplo. */
  var all = state.notifications.filter(function (n) { return n.to === state.me && !C.isDemoNotif(state, n); });
  /* v1.5.17 punto 4: los avisos de sistema (batería baja/llena) no van
     con los de WordRed: van en el apartado de otras apps/sistema. */
  var sysList = all.filter(function (n) { return n.type === 'system'; });
  var list = all.filter(function (n) { return n.type !== 'system'; });
  var el = $('notifList');
  var icons = { like: 'heart', comment: 'message', request: 'users', friend: 'users', message: 'message', share: 'share', group: 'users', post: 'file', pagepost: 'file', grouppost: 'file', tag: 'tag', system: 'battery', mention: 'tag', birthday: 'users', liveInvite: 'videocam' }; /* 1.5.26 (24/5/23) */ /* Web 1.1: sin avisos de actualización ni de Windows. */
  var wrHtml = '';
  if (!list.length) {
    wrHtml = '<div class="empty"><div class="big">' + ic('bell', 34) + '</div><p>Sin notificaciones todavía.</p><p class="tiny">Cuando alguien reaccione, comente o te escriba, aparecerá aquí.</p></div>';
  } else {
    wrHtml = list.slice(0, 100).map(function (n) {
      var name = (n.type === 'update' || n.type === 'windows') ? 'WordRed' : profileName(n.from);
      var click = (n.type === 'update' || n.type === 'windows') ? 'window.__wrOpenSettings()' /* Web 1.1: los avisos viejos de actualización/Windows abren Ajustes. */
        : n.type === 'message' ? 'window.__wrOpenChat(\'' + n.from + '\')'
        : n.type === 'mention' ? 'window.__wrOpenPost(\'' + n.refId + '\')' /* 1.5.26 (24): la mención abre el comentario */
        : n.type === 'birthday' ? 'window.__wrOpenProfile(\'' + n.from + '\')' /* 1.5.26 (5): el cumpleaños abre su perfil */
        : n.type === 'liveInvite' ? 'window.__wrRespondLiveInviteDialog(\'' + n.refId + '\')' /* 1.5.26 (23): aceptar o rechazar */
        : (n.refId && n.type !== 'request' ? 'window.__wrOpenPost(\'' + n.refId + '\')' : 'window.__wrOpenProfile(\'' + n.from + '\')');
      return '<div class="glass card notif' + (n.read ? '' : ' unread') + '" onclick="' + click + '">' +
        '<span style="color:var(--mut)">' + ic(icons[n.type] || 'bell', 20) + '</span>' +
        '<div class="who"><b>' + esc(name) + '</b> ' + esc(n.text) + '<div class="tiny">' + C.timeAgo(n.createdAt) + ' · ' + C.formatDateTime(n.createdAt) + '</div>' +
        (n.read ? '' : '<span class="notifdot"></span>') + '</div>';
    }).join('');
  }
  el.innerHTML = '<h3 class="sectitle">WordRed</h3>' + wrHtml +
    (sysList.length ? '<h3 class="sectitle" style="margin-top:16px">Sistema</h3>' +
    sysList.map(function (n) {
      /* Avisos de sistema (batería): al tocarlos solo se marcan leídos,
         no llevan a ningún lado. */
      return '<div class="glass card notif' + (n.read ? '' : ' unread') + '" onclick="window.__wrReadNotif(\'' + n.id + '\')">' +
        '<span style="color:var(--mut)">' + ic('battery', 20) + '</span>' +
        '<div class="who"><b>Sistema</b> ' + esc(n.text) + '<div class="tiny">' + C.timeAgo(n.createdAt) + ' · ' + C.formatDateTime(n.createdAt) + '</div></div>' +
        (n.read ? '' : '<span class="notifdot"></span>') + '</div>';
    }).join('') : ''); /* Web 1.1: sin notificaciones de otras apps (necesitan el teléfono). */
}
$('notifReadAll').addEventListener('click', function () {
  C.markNotificationsRead(state, state.me);
  save();
  renderNotifs();
  updateBadges();
});

window.__wrReadNotif = function (id) {
  var n = state.notifications.find(function (x) { return x.id === id; });
  if (n && !n.read) { n.read = true; save(); renderNotifs(); updateBadges(); }
};

/* ---------------- búsqueda ---------------- */
$('searchInput').addEventListener('input', function () { renderSearch(); });
/* Web 1.2: el buscador del Inicio se quitó (la búsqueda sigue en la vista «Buscar»). */
function renderSearch() {
  var q = ($('searchInput').value || '').trim();
  var el = $('searchResults');
  var savedLinksCard1526 = '<h3 class="sectitle">Enlaces guardados</h3><div class="glass card row" onclick="window.__wrOpenSavedLinks()"><div class="who"><b> Enlaces guardados (' + (state.savedLinks || []).length + ')</b><span class="muted">Toca para ver tu lista</span></div></div>'; /* 1.5.26 (59) */
  if (!q) { el.innerHTML = '<p class="muted">Busca personas por nombre, publicaciones por palabras, grupos o #etiquetas.</p>' + savedLinksCard1526; return; }
  var res = C.searchAll(state, state.me, q);
  var html = '';
  if (res.people.length) {
    html += '<h3 class="sectitle">Personas</h3>' + res.people.map(function (p) {
      return personRow(p.phone, '', p.phone === state.me ? '' : '<button class="btn ghost small" onclick="event.stopPropagation();window.__wrOpenProfile(\'' + p.phone + '\')">Ver perfil</button>');
    }).join('');
  }
  if (res.groups.length) {
    html += '<h3 class="sectitle">Grupos</h3>' + res.groups.map(function (g) {
      return '<div class="glass card row" onclick="window.__wrOpenGroup(\'' + g.id + '\')"><div class="who"><b>' + esc(g.name) + '</b><span class="muted">' + esc(g.desc || '') + ' · ' + g.members.length + ' miembros</span></div></div>';
    }).join('');
  }
  if (res.posts.length) {
    /* 1.5.26 (45): el filtro de palabras también se aplica en la búsqueda. */
    var filteredPosts1526 = C.filterFeedWords(res.posts, state.wordFilter || []).visible;
    html += '<h3 class="sectitle">Publicaciones</h3>' + filteredPosts1526.slice(0, 20).map(function (p) { return postCardHtml(p); }).join('');
  }
  html += savedLinksCard1526;
  if (!res.people.length && !res.groups.length && !res.posts.length) {
    html = '<div class="empty"><div class="big">' + ic('search', 34) + '</div><p>Sin resultados para "' + esc(q) + '".</p><p class="tiny">Prueba con otra palabra o con #etiqueta.</p></div>' + savedLinksCard1526;
  }
  el.innerHTML = html;
}



/* ---------------- ajustes ---------------- */
/* v1.5.15 (punto 11): la barra de abajo respeta la barra de navegación
   del sistema cuando el teléfono usa los 3 botones. Causa: el relleno
   que applySystemBarPadding pone al WebView (1.5.9) mueve el contenido
   pero NO los elementos position:fixed, y env(safe-area-inset-bottom)
   es 0 dentro de un WebView de Android, así que #bottomNav quedaba en
   el borde inferior de la pantalla, encima de los botones del sistema.
   El puente dice la altura en píxeles CSS (0 en modo gestos: sin hueco);
   la variable --sys-nav-bottom sube la barra y el despeje del contenido. */
function applyNavInset(px) {
  try {
    var n = parseInt(px, 10);
    if (isNaN(n) || n < 0) n = 0;
    document.documentElement.style.setProperty('--sys-nav-bottom', n + 'px');
  } catch (e) {}
}
window.__wrNavInset = function (px) { applyNavInset(px); };
function initNavInset() {
  try {
    if (window.AndroidBridge && AndroidBridge.getNavBarHeight) applyNavInset(AndroidBridge.getNavBarHeight());
  } catch (e) {}
}
initNavInset();;

