/* ---- notificaciones fuera de la app (v1.5) ----
   Solo se avisa si la app está en segundo plano o cerrada y si ese tipo
   de aviso está activado en Ajustes. El destino (target) lo usa la app
   nativa para abrir el apartado correcto al tocar el aviso. */
function maybeNotify(type, title, text, target, actions) {
  if (!appHidden) return;
  /* 1.5.26 (49): en horas tranquilas los avisos no suenan ni aparecen en
     el teléfono; se guardan en la campana. Las llamadas sí suenan. */
  if (type !== 'call' && type !== 'calls' && inQuietHours1526()) return;
  /* 1.5.26 (31): si el remitente está silenciado, no hay aviso de teléfono
     (el aviso sí queda en la campana). */
  if (target && target.phone && isMuted1526(target.phone)) return;
  if (target && target.from && isMuted1526(target.from)) return;
  var pref = 'notif' + type.charAt(0).toUpperCase() + type.slice(1);
  if (state.settings[pref] === false) return;
  if (!window.AndroidBridge || !AndroidBridge.showNotification) return;
  try {
    /* 1.5.26 (64): cada chat puede tener su propio sonido. */
    var phone = (target && (target.phone || target.from)) || null;
    if ((type === 'message' || type === 'messages') && phone && chatSound1526(phone) !== 'bell' && AndroidBridge.showChatNotification) {
      AndroidBridge.showChatNotification(title, text, JSON.stringify(target || { kind: 'home' }), chatSound1526(phone));
      return;
    }
    AndroidBridge.showNotification(title, text, JSON.stringify(target || { kind: 'home' }), actions ? JSON.stringify(actions) : '');
  } catch (e) {}
}
function unreadActivityCount() {
  var n = 0;
  if (state.me) {
    C.conversationList(state, state.me).forEach(function (c) { n += c.unread; });
    n += C.unreadNotifications(state, state.me);
  }
  return n;
}
/* Invitación ocasional a volver: solo con actividad sin leer, como
   máximo una vez al día y nunca con la app activa (la regla vive en
   C.reengageDue y la última vez la guarda la app nativa). */
function maybeScheduleReengage() {
  if (!appHidden) return;
  if (!window.AndroidBridge || !AndroidBridge.scheduleReengagement) return;
  var last = 0;
  try { if (AndroidBridge.getReengageLast) last = Number(AndroidBridge.getReengageLast() || 0); } catch (e) {}
  var settings = Object.assign({}, state.settings, { reengageLast: last });
  if (!C.reengageDue(settings, unreadActivityCount(), Date.now()).due) return;
  try { AndroidBridge.scheduleReengagement(4 * 60 * 60 * 1000); } catch (e) {}
}
document.addEventListener('visibilitychange', function () {
  appHidden = document.hidden;
  if (appHidden) maybeScheduleReengage();
  else if (window.AndroidBridge && AndroidBridge.cancelReengagement) {
    try { AndroidBridge.cancelReengagement(); } catch (e) {}
  }
});
/* La app nativa entrega aquí el destino de un aviso tocado. */
window.__onNotifTarget = function (target) {
  var t = target;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { return; } }
  if (!t || !t.kind) return;
  if (t.kind === 'chat') {
    go('messages');
    if (t.phone) window.__wrOpenChat(t.phone);
  } else if (t.kind === 'shorts') {
    /* v1.5.12: el recordatorio de Shorts abre la sección de Shorts. */
    go('shorts');
  } else if (t.kind === 'post') {
    if (t.id) window.__wrOpenPost(t.id);
  } else if (t.kind === 'call') {
    if (t.phone && call.state === 'incoming' && call.peer === t.phone) { showOverlay('callOverlay'); renderCallIncoming(); }
    else if (t.phone) { go('messages'); window.__wrOpenChat(t.phone); }
  } else if (t.kind === 'live') {
    if (t.id) joinLive(t.id);
  } else if (t.kind === 'birthday') {
    /* 1.5.26 (5): la notificación de cumpleaños abre el perfil de quien cumple. */
    if (t.phone) window.__wrOpenProfile(t.phone);
    else go('friends');
  } else if (t.kind === 'event') {
    /* 1.5.26 (27): el recordatorio de evento abre el evento. */
    if (t.id || t.eventId) window.__wrOpenEvent(t.id || t.eventId);
    else go('feed');
  } else if (t.kind === 'scheduled') {
    /* 1.5.26 (6): el aviso de publicación programada abre la lista. */
    openScheduled1526();
  } else {
    go('feed');
  }
};
/* Acciones de la notificación de llamada entrante (Contestar/Rechazar). */
window.__onCallAction = function (action, phone) {
  if (action === 'answer') {
    if (call.state === 'incoming' && (!phone || call.peer === phone)) acceptCall();
    else if (phone) { go('messages'); window.__wrOpenChat(phone); }
  } else if (action === 'reject') {
    if (call.state === 'incoming' && (!phone || call.peer === phone)) window.__wrRejectCall();
  }
};
/* v1.5.12: la app se abrió desde la notificación de llamada del servicio
   en segundo plano. La oferta guardada se recoge con takePendingCall.
   Si todavía no hay sesión (la página cargó antes de entrar), se guarda
   y se procesa al entrar en la app. */
var pendingBgCall = null; // {action, raw}
function processPendingBgCall() {
  if (!pendingBgCall) return;
  if (!state.me) return;
  var item = pendingBgCall;
  pendingBgCall = null;
  var pc = null;
  try { pc = JSON.parse(item.raw); } catch (e) { return; }
  if (!pc || !pc.from) return;
  call.peer = pc.from;
  call.offer = pc.offer || null;
  call.withVideo = !!pc.withVideo;
  call.state = 'incoming';
  if (item.action === 'answer') {
    acceptCall();
  } else {
    renderCallIncoming();
    showOverlay('callOverlay');
    startIncomingRing();
  }
}
window.__onBackgroundCall = function (action) {
  var raw = '';
  try { if (window.AndroidBridge && AndroidBridge.takePendingCall) raw = AndroidBridge.takePendingCall(); } catch (e) {}
  if (!raw) return;
  pendingBgCall = { action: action || 'open', raw: raw };
  processPendingBgCall();
};
/* ---- vinculación automática en segundo plano (v1.3) ----
   La app se conecta sola a la dirección que trae dentro, como cualquier
   app normal: pide el código de 6 dígitos y lo verifica sin mostrar
   nada. Sin Twilio, la respuesta trae el código directamente y se
   verifica en el mismo momento. Con Twilio, el código llega por SMS y
   la app lo lee sola con SMS Retriever (__onSmsCode). Si no hay
   conexión, no se muestra ningún error: la app sigue en modo local y
   lo reintenta sola al entrar o al recuperar la conexión. */
var autoLinkInFlight = false;
var autoLinkLastTry = 0;
var serverLinkWaiting = false;
async function autoLinkServer() {
  var base = C.serverBase(state);
  if (!base || !state.me || state.settings.serverToken) return false;
  /* v2.9: las cuentas de correo/Google ya traen su token del servidor;
     pedir un código de teléfono para un correo no tiene sentido. */
  if (C.isEmailIdentity(state.me)) return false;
  if (autoLinkInFlight) return false;
  if (Date.now() - autoLinkLastTry < 60000) return false;
  autoLinkLastTry = Date.now();
  autoLinkInFlight = true;
  try {
    var body = { phone: state.me };
    try {
      if (window.AndroidBridge && AndroidBridge.getSmsAppHash) {
        var h = AndroidBridge.getSmsAppHash();
        if (h) body.appHash = h;
      }
    } catch (e) {}
    var r = await C.serverFetch(state, '/api/auth/request-code', 'POST', body);
    if (!r.ok) return false;
    if (r.data && r.data.devCode) {
      return await verifyServerCodeSilent(r.data.devCode);
    }
    serverLinkWaiting = true;
    try { if (window.AndroidBridge && AndroidBridge.startSmsRetriever) AndroidBridge.startSmsRetriever(); } catch (e) {}
    /* Si el SMS no llega en 5 minutos, se deja de esperar: el próximo
       intento será al entrar de nuevo o al recuperar la conexión. */
    setTimeout(function () { serverLinkWaiting = false; }, 5 * 60 * 1000);
    return false;
  } catch (e) { return false; }
  finally { autoLinkInFlight = false; }
}
async function verifyServerCodeSilent(code) {
  var base = C.serverBase(state);
  if (!base || !state.me) return false;
  var r = await C.serverFetch(state, '/api/auth/verify', 'POST', { phone: state.me, code: String(code || '').trim() });
  if (!r.ok) return false;
  state.settings.serverToken = (r.data && r.data.token) || '';
  if (!state.settings.serverToken) return false;
  save();
  connectServer();
  pullFromServer();
  /* v1.4: si el perfil quedó pendiente (foto o portada sin subir),
     se sube ahora que ya hay sesión en el servidor. */
  if (state.settings.profileDirty) pushProfileToServer();
  return true;
}
