    showUploadProgress(10, 'Subiendo foto de perfil…');
    var photoUrl = null;
    try { photoUrl = await uploadMediaItemToServer({ src: p.photo, type: 'image' }, function (pc) { showUploadProgress(pc, 'Subiendo foto de perfil…'); }); } catch (e) { photoUrl = null; }
    hideUploadProgress();
