  updateLiveRecLabel();
  var vv = $('liveVideo');
  if (vv) { try { vv.style.filter = ''; vv.style.transform = ''; } catch (e) {} }
  if (liveStream) { try { liveStream.getTracks().forEach(function (t) { t.stop(); }); } catch (e) {} }
  liveStream = null;
  var v = $('liveVideo');
