  liveCoHostAwaitingAnswer = false;
  if (liveCoHostPublishPc) { try { liveCoHostPublishPc.close(); } catch (e) {} liveCoHostPublishPc = null; }
  if (liveCoHostLocalStream) { liveCoHostLocalStream.getTracks().forEach(function (t) { try { t.stop(); } catch (e) {} }); liveCoHostLocalStream = null; }
  Object.keys(liveCoHostPcs).forEach(function (k) { try { liveCoHostPcs[k].close(); } catch (e) {} });
  liveCoHostPcs = {};
