    liveFilterCanvas.width = vw;
    liveFilterCanvas.height = vh;
    liveFilterSrc.srcObject = (liveSource === 'screen' && liveScreenStream) ? liveScreenStream : liveStream;
    try { var p = liveFilterSrc.play(); if (p && p.catch) p.catch(function () {}); } catch (e) {}
    liveFilterRunning = true;
