  (state.groupChats || []).forEach(function (g) { if (g && g.unread && state.me && g.unread[state.me]) unread += g.unread[state.me]; });
  return '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><div><b>Mensajería</b><div class="tiny muted">' + (unread > 0 ? unread + ' mensaje' + (unread === 1 ? '' : 's') + ' sin leer' : 'Sin mensajes sin leer') + '</div></div><button type="button" class="btn small" data-hw-open-messages="1">Abrir mensajes</button></div>';
