/* ---- 40. Volver donde te quedaste ---- */
/* 1.5.59: marca de sesión viva para distinguir el lanzamiento limpio
   del regreso tras morir por poca RAM. Se escribe cada vez que se
   guarda la posición del muro y al entrar a la app; se borra solo al
   cerrarse bien (pagehide/beforeunload). Si Android mata el proceso
   por poca RAM, el cierre no avisa y la marca queda: al volver, la
   app restaura donde quedó en lugar de empezar arriba. */
var ALIVE_KEY_1559 = 'wordred_alive1559';
var aliveBound1559 = false;
function markAlive1559() { try { localStorage.setItem(ALIVE_KEY_1559, String(Date.now())); } catch (e) {} }
function clearAlive1559() { try { localStorage.removeItem(ALIVE_KEY_1559); } catch (e) {} }
function isCleanLaunch1559() { try { return !localStorage.getItem(ALIVE_KEY_1559); } catch (e) { return true; } }
function bindAlive1559() {
  if (aliveBound1559 || typeof window === 'undefined' || !window.addEventListener) return;
  aliveBound1559 = true;
  window.addEventListener('pagehide', clearAlive1559);
  window.addEventListener('beforeunload', clearAlive1559);
}
function saveFeedPosition1526() {
  var arts = document.querySelectorAll('#feed article[data-post]');
  var best = null, bestTop = Infinity;
  arts.forEach(function (a) {
    try {
      var r = a.getBoundingClientRect();
      if (r.top >= 0 && r.top < bestTop) { bestTop = r.top; best = a.getAttribute('data-post'); }
    } catch (e) {}
  });
  if (best) { state.lastFeedPostId = best; state.lastFeedAt = Date.now(); save(); }
  markAlive1559(); /* 1.5.59: mientras hay muro, la sesión sigue viva */
}
/* 1.5.28: el inicio no se mueve si estás en otro apartado — la posición
   solo se restaura al volver al inicio (nunca mientras estás en otra vista,
   donde un redibujado del inicio no debe desplazar lo que estás viendo). */
function restoreFeedPosition1526() {
  /* 1.5.59: en el lanzamiento limpio no se restaura la posición: el inicio empieza desde arriba. */
  if (skipFeedRestoreOnce1557) { skipFeedRestoreOnce1557 = false; return; }
  if (currentView !== 'feed') return; /* 1.5.28: fuera del inicio no se restaura. */
  if (feedRestoreDone || !state.lastFeedPostId) return;
  feedRestoreDone = true;
  /* Web 1.1: ir de inmediato a la publicación guardada (sin parpadear en 0) y re-afirmar a los 300 ms por si las imágenes mueven el muro. */
  try { var elNow11 = document.querySelector('#feed article[data-post="' + state.lastFeedPostId + '"]'); if (elNow11) elNow11.scrollIntoView({ block: 'start' }); } catch (e) {}
  setTimeout(function () {
    /* Web 1.1: si hubo doble toque en Inicio, esta restauración queda cancelada (siempre arriba). */
    if (skipFeedRestoreOnce1557) { skipFeedRestoreOnce1557 = false; return; }
    /* 1.5.29: si ya saliste del inicio en esos 300 ms, no desplazar nada
       (antes el desplazamiento se disparaba tarde, ya en otro apartado). */
    if (currentView !== 'feed') return;
    var el = document.querySelector('#feed article[data-post="' + state.lastFeedPostId + '"]');
    if (!el) return;
    /* Web 1.1: si ya te moviste en esos 300 ms (por ejemplo,
       subiste a mano hasta arriba), la publicación guardada ya no está
       cerca de arriba: no devolverte a la fuerza (antes, este
       temporizador bajaba de nuevo la página aunque se acabara de subir). */
    var top11 = el.getBoundingClientRect().top;
    if (top11 < -300 || top11 > 300) return;
    try { el.scrollIntoView({ block: 'start' }); } catch (e) { window.scrollTo(0, el.offsetTop); }
  }, 300);
}

/* 1.5.59 (sustituye la regla de la 1.5.57): al abrir la app DESDE
   CERRADA, el inicio empieza desde arriba (scroll 0). La posición
   guardada («volver donde te quedaste», 1.5.26) se salta solo en el
   lanzamiento limpio; al salir del inicio y volver en la misma sesión,
   la restauración sigue igual; y al VOLVER a la app — aunque hayas
   estado más de un minuto fuera, o aunque Android la haya matado por
   poca RAM — también se restaura donde quedó. La marca de sesión viva
   (wordred_alive1559) distingue el lanzamiento limpio del regreso:
   se escribe al guardar la posición y al entrar, y solo se borra al
   cerrarse bien (pagehide/beforeunload). */
var skipFeedRestoreOnce1557 = false;
var appHiddenSince1557 = 0;
var appReturnBound1557 = false;
function resetHomeToTop1557() {
  skipFeedRestoreOnce1557 = true;
  try { if (typeof go === 'function') go('feed'); } catch (e) {}
  try { window.scrollTo(0, 0); } catch (e) {}
}
/* 1.5.59: la regla de la 1.5.57 (volver arriba tras más de 60 s fuera)
   YA NO EXISTE: al volver a la app te quedas donde ibas. Esta función
   queda como no-op para no romper quien la llamaba; la posición del
   muro ahora la cuidan isCleanLaunch1559/markAlive1559. */
function bindAppReturnHome1557() {
  return;
}

