/* ---- 4. Vistas de publicaciones (observador de visibilidad) ---- */
function recordPostView1526(post) {
  if (!post || !state.me || post.author === state.me) return;
  if (state.postViewed[post.id]) return;
  state.postViewed[post.id] = true;
  save();
  pushToServer('/api/posts/' + encodeURIComponent(post.id) + '/view', 'POST', {}).catch(function () {});
}
var postViewObserver = null;
function observePostViews1526() {
  if (typeof IntersectionObserver === 'undefined') return;
  if (postViewObserver) postViewObserver.disconnect();
  postViewObserver = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      if (!en.isIntersecting || en.intersectionRatio < 0.5) return;
      var id = en.target.getAttribute('data-post');
      var post = state.posts.filter(function (p) { return p.id === id; })[0];
      if (post) recordPostView1526(post);
    });
  }, { threshold: 0.5 });
  document.querySelectorAll('#feed article[data-post], #ownProfile article[data-post]').forEach(function (a) { postViewObserver.observe(a); });
}

