/* ---- 50. Compartir un Short en tu historia ---- */
async function shareShortToStory1526(postId) {
  var post = state.posts.filter(function (p) { return p.id === postId; })[0];
  if (!post) return;
  var r = C.createStory(state, state.me, {
    text: 'Short de ' + profileName(post.author),
    media: '',
    mediaType: ''
  });
  /* La historia es una referencia (portada + enlace al Short), no una
     copia del video: el id del Short viaja en sharedShortId. */
  if (!r.ok) { toast(r.error); return; }
  r.story.sharedShortId = postId;
  /* 1.5.58: la historia se confirma en el servidor (si el envío falla,
     se reintenta sola y se avisa). */
  if (bgUploadHasServer1529()) r.story.pendingSync = true;
  save();
  confirmStoryPublish1529(r.story);
  renderStories();
  toast('Short compartido en tu historia.');
}
window.__wrShareShortToStory = function (postId) { shareShortToStory1526(postId); };

/* ---- 3. Dueto en Shorts ---- */
function openDuet1526(postId) {
  var post = state.posts.filter(function (p) { return p.id === postId; })[0];
  if (!post) return;
  duetOrig = post;
  $('duetOrigTitle').textContent = 'Dueto con ' + profileName(post.author);
  var origVideo = (post.mediaList && post.mediaList.length ? post.mediaList : [{ src: post.media, type: post.mediaType }]).filter(function (m) { return m.src; })[0];
  $('duetOrigVideo').innerHTML = origVideo
    ? (origVideo.type === 'video' || /\.mp4(\?|$)|\.webm(\?|$)/i.test(origVideo.src)
      ? '<video id="duetOrigEl" src="' + esc(origVideo.src) + '" loop playsinline style="width:100%;height:100%;object-fit:cover"></video>'
      : '<img src="' + esc(origVideo.src) + '" style="width:100%;height:100%;object-fit:cover" alt="Original">')
    : '<div class="muted" style="padding:20px">Sin video original.</div>';
  $('duetCamVideo').innerHTML = '<p class="muted" style="padding:20px">Toca “Empezar a grabar” para encender tu cámara.</p>';
  $('duetRecordBtn').textContent = '● Empezar a grabar';
  $('duetPublishBtn').classList.add('hidden');
  showOverlay('duetOverlay');
}
async function duetStartRecording1526() {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { toast('Este teléfono no permite grabar video.'); return; }
  try {
    duetStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: true });
  } catch (e) {
    toast('No se pudo usar la cámara o el micrófono. Revisa los permisos: sin ellos no se puede grabar el dueto.');
    return;
  }
  $('duetCamVideo').innerHTML = '<video id="duetCamEl" autoplay muted playsinline style="width:100%;height:100%;object-fit:cover"></video>';
  var camEl = $('duetCamEl');
  if (camEl) camEl.srcObject = duetStream;
  var origEl = $('duetOrigEl');
  if (origEl && origEl.play) { try { origEl.play(); } catch (e) {} }
  duetChunks = [];
  try {
    duetRecorder = new MediaRecorder(duetStream);
  } catch (e) {
    toast('Este teléfono no puede grabar video.');
    duetStream.getTracks().forEach(function (t) { t.stop(); });
    duetStream = null;
    return;
  }
  duetRecorder.ondataavailable = function (ev) { if (ev.data && ev.data.size) duetChunks.push(ev.data); };
  duetRecorder.start(500);
  duetRecording = true;
  $('duetRecordBtn').textContent = '■ Detener grabación';
  toast('Grabando tu dueto mientras suena el original.');
}
function duetStopRecording1526() {
  if (!duetRecorder || !duetRecording) return;
  duetRecording = false;
  duetRecorder.onstop = function () {
    if (duetStream) duetStream.getTracks().forEach(function (t) { t.stop(); });
    $('duetPublishBtn').classList.remove('hidden');
    $('duetRecordBtn').textContent = '● Volver a grabar';
    toast('Grabación lista. Revísala y publícala como dueto.');
  };
  try { duetRecorder.stop(); } catch (e) {}
  var origEl = $('duetOrigEl');
  if (origEl && origEl.pause) origEl.pause();
}
var _duetRecBtn = $('duetRecordBtn');
if (_duetRecBtn) _duetRecBtn.addEventListener('click', function () {
  if (duetRecording) duetStopRecording1526();
  else duetStartRecording1526();
});
var _duetPubBtn = $('duetPublishBtn');
if (_duetPubBtn) _duetPubBtn.addEventListener('click', async function () {
  if (!duetOrig || !duetChunks.length) { toast('Primero graba tu video.'); return; }
  var blob = new Blob(duetChunks, { type: duetRecorder && duetRecorder.mimeType ? duetRecorder.mimeType : 'video/webm' });
  if (!blob.size) { toast('La grabación salió vacía. No se publicó ningún dueto.'); return; }
  var file = new File([blob], 'dueto.webm', { type: blob.type });
  showUploadProgress(10, 'Subiendo tu dueto…');
  var url = null;
  try { url = await uploadFileToServer(file, function (p) { showUploadProgress(p, 'Subiendo tu dueto…'); }); } catch (e) { url = null; }
  hideUploadProgress();
  if (!url) { toast('No se pudo subir tu video. No se publicó ningún dueto.'); return; }
  var r = C.createPost(state, state.me, {
    text: '', media: url, mediaType: 'video',
    duetOf: { postId: duetOrig.id, author: duetOrig.author },
    privacy: 'Público'
  });
  if (!r.ok) { toast(r.error); return; }
  publishCreatedPost1529(r.post, 'Dueto publicado.');
  hideOverlay('duetOverlay');
  duetOrig = null; duetChunks = [];
  go('feed');
});
var _duetCloseBtn = $('duetCloseBtn');
if (_duetCloseBtn) _duetCloseBtn.addEventListener('click', function () {
  if (duetRecording && duetRecorder) { try { duetRecorder.stop(); } catch (e) {} }
  if (duetStream) duetStream.getTracks().forEach(function (t) { t.stop(); });
  duetStream = null; duetOrig = null; duetRecording = false;
  hideOverlay('duetOverlay');
});

/* 1.5.26: botones del compositor (borrador/programadas) y los dos
   selectores de archivo que faltaban: fotos de la encuesta (26) y
   portada de la nota de voz de la historia (17). Sin subida no se
   guarda nada: si la subida falla, no se publica ni se guarda nada. */
