/* ---- 12. Vender con carrito ---- */
var cartCoupon = null; // {code, discountPct}
function cartTotal1526() {
  var t = C.cartTotal(state);
  var discount = 0;
  if (cartCoupon && t.total > 0) {
    discount = t.total - C.couponDiscounted(t.total, cartCoupon.discountPct);
  }
  return { lines: t.lines, count: t.count, subtotal: t.total, discount: discount, total: t.total - discount };
}
function openCart1526() {
  var t = cartTotal1526();
  var body = $('cartBody');
  body.innerHTML = t.lines.length ? t.lines.map(function (ln) {
    return '<div class="glass card row"><div class="who"><b>' + esc(ln.title) + '</b><span class="muted">$' + ln.price.toLocaleString('es-MX') + ' × ' + ln.qty + ' = $' + ln.subtotal.toLocaleString('es-MX') + ' MXN · Vendedor: ' + esc(profileName(ln.seller)) + '</span></div>' +
      '<span style="display:flex;gap:4px;align-items:center"><button class="btn ghost small" onclick="window.__wrCartQty(\'' + ln.listingId + '\',-1)">−</button><b>' + ln.qty + '</b><button class="btn ghost small" onclick="window.__wrCartQty(\'' + ln.listingId + '\',1)">＋</button><button class="btn ghost small" onclick="window.__wrCartRemove(\'' + ln.listingId + '\')">✕</button></span></div>';
  }).join('') +
    '<div class="glass card" style="display:block;margin-top:10px">' +
    '<div style="display:flex;gap:8px"><input id="cartCouponInput" type="text" placeholder="Código de cupón" style="flex:1;text-transform:uppercase" value="' + esc(cartCoupon ? cartCoupon.code : '') + '"><button class="btn small" onclick="window.__wrApplyCartCoupon()">Aplicar</button></div>' +
    (cartCoupon ? '<p class="tiny" style="color:#8fd0ff;margin-top:6px">Cupón ' + esc(cartCoupon.code) + ': −' + cartCoupon.discountPct + '% <button class="tiny" onclick="window.__wrClearCartCoupon()">Quitar</button></p>' : '') +
    '<p style="margin-top:10px">Subtotal: $' + t.subtotal.toLocaleString('es-MX') + ' MXN</p>' +
    (t.discount ? '<p>Descuento: −$' + t.discount.toLocaleString('es-MX') + ' MXN</p>' : '') +
    '<p><b>Total: $' + t.total.toLocaleString('es-MX') + ' MXN</b></p>' +
    '<p class="tiny muted">El pago es manual: pagas el total por transferencia, como acuerdes con el vendedor.</p></div>' +
    '<div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><button class="btn" onclick="window.__wrSendOrder(\'chat\')">Enviar pedido por WordRed</button><button class="btn ghost" onclick="window.__wrSendOrder(\'whatsapp\')">Enviar pedido por WhatsApp</button></div>'
    : '<p class="muted">Tu carrito está vacío. Toca “Añadir al carrito” en un anuncio.</p>';
  showOverlay('cartOverlay');
}
window.__wrCartAdd = function (listingId) {
  var l = state.listings.filter(function (x) { return x.id === listingId; })[0];
  if (!l || l.status === 'Vendido') { toast('Ese anuncio ya no está en venta.'); return; }
  C.cartAdd(state, listingId, 1);
  save();
  toast('Añadido al carrito.');
};
window.__wrCartQty = function (listingId, delta) {
  var it = (state.cart || []).filter(function (x) { return x.listingId === listingId; })[0];
  if (!it) return;
  C.cartSetQty(state, listingId, it.qty + delta);
  save();
  openCart1526();
};
window.__wrCartRemove = function (listingId) {
  C.cartRemove(state, listingId);
  save();
  openCart1526();
};
window.__wrApplyCartCoupon = async function () {
  var code = C.normalizeCouponCode($('cartCouponInput') ? $('cartCouponInput').value : '');
  if (!code) { toast('Escribe el código del cupón.'); return; }
  var t = cartTotal1526();
  if (!t.lines.length) { toast('El carrito está vacío.'); return; }
  var first = t.lines[0];
  var r = await pushToServer('/api/coupons/' + encodeURIComponent(code) + '/apply', 'POST', { listingId: first.listingId });
  if (!r.ok) { toast(r.error || 'Ese cupón no aplica.'); return; }
  cartCoupon = { code: code, discountPct: (r.data && r.data.discountPct) || 0 };
  openCart1526();
  toast('Cupón aplicado: −' + cartCoupon.discountPct + '%.');
};
window.__wrClearCartCoupon = function () { cartCoupon = null; openCart1526(); };
window.__wrSendOrder = async function (via) {
  var t = cartTotal1526();
  if (!t.lines.length) { toast('El carrito está vacío.'); return; }
  var sellers = {};
  t.lines.forEach(function (ln) { (sellers[ln.seller] = sellers[ln.seller] || []).push(ln); });
  var sellerPhones = Object.keys(sellers);
  if (sellerPhones.length > 1) { toast('Tu carrito tiene productos de varios vendedores. Envía el pedido por vendedor: quita los de uno y envía, luego los del otro.'); return; }
  var seller = sellerPhones[0];
  var msg = C.orderMessageText(t.lines, t.total, (myProfile() || {}).name || 'Yo');
  if (cartCoupon) msg += '\nCupón aplicado: ' + cartCoupon.code + ' (−' + cartCoupon.discountPct + '%).';
  var sent = false;
  if (via === 'whatsapp') {
    var wa = '';
    var l = state.listings.filter(function (x) { return x.id === t.lines[0].listingId; })[0];
    if (l && l.whatsapp) wa = String(l.whatsapp).replace(/[^0-9]/g, '');
    if (!wa) wa = String(seller).replace(/[^0-9]/g, '');
    if (!wa) { toast('Ese vendedor no tiene WhatsApp registrado. Envíalo por WordRed.'); return; }
    window.__wrOpenUrl(encodeURIComponent('https://wa.me/' + wa + '?text=' + encodeURIComponent(msg)));
    sent = true;
  } else {
    var r = C.sendMessage(state, state.me, seller, msg, '', '', null);
    if (!r.ok) { toast(r.error); return; }
    save();
    pushMessageToServer(r.message, seller);
    sent = true;
  }
  if (sent) {
    state.cart = [];
    cartCoupon = null;
    save();
    hideOverlay('cartOverlay');
    toast('Pedido enviado. El carrito se vació. El pago sigue siendo manual.');
  }
};

