/* ---- 5. Cumpleaños en la campana ---- */
function checkBirthdays1526() {
  if (!state.me) return;
  var todays = C.todaysBirthdays(state);
  todays.forEach(function (b) {
    var refId = 'bd_' + b.phone + '_' + C.todayStr();
    var already = state.notifications.some(function (n) { return n.type === 'birthday' && n.refId === refId && n.to === state.me; });
    if (already) return;
    var item = C.notify(state, { type: 'birthday', from: b.phone, to: state.me, text: 'Hoy es el cumpleaños de ' + b.name + ' ', refId: refId });
    if (item) {
      save();
      updateBadges();
      try {
        if (window.AndroidBridge && AndroidBridge.showNotification) AndroidBridge.showNotification('WordRed', 'Hoy es el cumpleaños de ' + b.name + ' ', JSON.stringify({ kind: 'profile', phone: b.phone }));
      } catch (e) {}
    }
  });
  var tomorrow = C.upcomingBirthdays(state, 1).filter(function (b) { return b.inDays === 1; });
  tomorrow.forEach(function (b) {
    var d = new Date();
    var at = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1, 9, 0, 0).getTime();
    scheduleLocalNotif1526('bd_' + b.phone, at, 'WordRed', 'Hoy es el cumpleaños de ' + b.name + ' ', { kind: 'birthday', phone: b.phone });
  });
}
function upcomingBirthdaysHtml1526() {
  var list = C.upcomingBirthdays(state, 30);
  if (!list.length) return '';
  return '<h3 class="sectitle"> Próximos cumpleaños</h3>' + list.map(function (b) {
    return '<div class="glass card row" onclick="window.__wrOpenProfile(\'' + b.phone + '\')">' + avatarHtml(b.phone) + '<div class="who"><b>' + esc(b.name) + '</b><span class="muted">' + (b.inDays === 0 ? '¡Hoy!' : b.inDays === 1 ? 'Mañana' : 'En ' + b.inDays + ' días') + ' · ' + esc(b.birthday.slice(5)) + '</span></div><button class="btn small" onclick="event.stopPropagation();window.__wrCongratulate1550(\'' + b.phone + '\')">🎂 Felicitar</button></div>';
  }).join('');
}

/* ---- 10. Cuenta verificada ---- */
async function openVerification1526() {
  $('verificationBody').innerHTML = '<p class="muted">Revisando tus requisitos…</p>';
  showOverlay('verificationOverlay');
  var r = await C.serverFetch(state, '/api/verification/status', 'GET');
  var missing = [];
  var verified = false;
  if (r.ok && r.data) {
    verified = !!r.data.verified;
    missing = (r.data.missing || []).map(function (m) { return typeof m === 'string' ? m : m.key; });
  } else {
    var p = myProfile();
    var myPosts = state.posts.filter(function (x) { return x.author === state.me && !x.pageId; }).length;
    missing = C.verificationMissing(p, myPosts, true, Date.now());
    verified = !!(p && p.verified);
  }
  var p2 = myProfile();
  verified = verified || !!(p2 && p2.verified);
  var html = '<p class="muted">La insignia verificada solo la concede el dueño de WordRed, después de revisar tu solicitud. Cumple los requisitos y envíala; él te avisa cuando la conceda.</p>' +
    C.VERIFICATION_KEYS.map(function (k) {
      var ok = missing.indexOf(k) < 0;
      return '<p style="margin-top:8px">' + (ok ? '✓' : '✗') + ' ' + esc(C.VERIFICATION_LABELS[k]) + '</p>';
    }).join('') +
    (verified
      ? '<p style="margin-top:12px;color:#8fd0ff;font-weight:700">✓ Tu cuenta ya está verificada.</p>'
      : '<div class="mt"><button class="btn" onclick="window.__wrRequestVerification()">Solicitar verificación</button></div>');
  $('verificationBody').innerHTML = html;
}
window.__wrRequestVerification = async function () {
  var r = await pushToServer('/api/verification/request', 'POST', {});
  if (!r.ok) { toast(r.error || 'No se pudo solicitar la verificación.'); return; }
  if (r.data && r.data.verified) {
    var p = myProfile();
    if (p) p.verified = true;
    save();
    pushProfileToServer();
    hideOverlay('verificationOverlay');
    renderOwnProfile();
    toast('¡Tu cuenta quedó verificada! ✓');
  } else if (r.data && r.data.pending) {
    /* Web 1.5 (5.0): la solicitud queda pendiente para el dueño. */
    hideOverlay('verificationOverlay');
    toast('Solicitud enviada. El dueño de WordRed la revisa y te avisa cuando te conceda la insignia.');
  } else {
    var missing = (r.data && r.data.missing) || [];
    toast('Todavía falta: ' + missing.map(function (m) { return C.VERIFICATION_LABELS[typeof m === 'string' ? m : m.key] || m; }).join(', ') + '.');
    openVerification1526();
  }
};

