var CHAT_EMOJIS_1562 = ['😀', '😃', '😄', '😁', '😆', '😅', '😂', '🤣', '😊', '😍', '😘', '😜', '🤪', '😎', '🥳', '😭', '😢', '😡', '😱', '🤔', '🙏', '👍', '👎', '👏', '🙌', '💪', '🔥', '❤️', '🧡', '💛', '💚', '💙', '💜', '🖤', '🤍', '💔', '💯', '✨', '🎉', '🎊', '🎂', '🍕', '🍔', '🍟', '☕', '🎵', '🎶', '⚽', '🏀', '🎮', '📱', '💡', '🎁', '🌹', '🌞', '🌙', '⭐', '🌈', '👋', '🤝', '👀', '💤', '😴', '🤒', '🤕'];
var chatPickerTab1562 = 'emoji';
