/* ---- 56. Reaccionar a un mensaje ---- */
function msgReactionsHtml1526(m) {
  var counts = C.msgReactionCounts(m);
  if (!counts.length) return '';
  var my = C.myMsgReaction(m, state.me);
  return '<div class="msgReactions" style="display:flex;gap:4px;margin-top:2px;cursor:pointer" onclick="window.__wrShowMsgReactions(\'' + m.id + '\')">' +
    counts.map(function (c) {
      return '<span style="background:' + (my === c.emoji ? 'rgba(224,20,48,.4)' : 'rgba(0,0,0,.25)') + ';border-radius:10px;padding:1px 6px;font-size:12px">' + c.emoji + ' ' + c.count + '</span>';
    }).join('') + '</div>';
}
window.__wrReactToMessage = async function (messageId, emoji) {
  if (!C.validateMsgReaction(emoji)) return;
  var m = findChatMessage1526(messageId);
  if (!m) return;
  /* Web 1.8: la reacción se aplica PRIMERO en este teléfono y se ve al instante. Antes solo se aplicaba si el servidor la aceptaba: un mensaje que el servidor no tiene (por ejemplo, el de la cuenta de ejemplo, que no existe en el servidor) devolvía 404 «Mensaje no encontrado» y la reacción nunca aparecía. El envío al servidor sigue, lo mejor que se pueda; si falla, la reacción ya quedó guardada aquí y no se revierte. */
  C.applyMsgReaction(m, state.me, profileName(state.me), emoji);
  save();
  renderChatMsgs();
  hideDialog();
  await pushToServer('/api/messages/' + encodeURIComponent(messageId) + '/react', 'POST', { emoji: emoji });
};
window.__wrShowMsgReactions = function (messageId) {
  var m = findChatMessage1526(messageId);
  if (!m || !m.reactions || !m.reactions.length) return;
  showDialog('Reacciones', m.reactions.map(function (r) {
    return '<div class="row" style="padding:6px 0">' + avatarHtml(r.phone) + '<div class="who"><b>' + esc(r.name || r.phone) + '</b></div><span style="font-size:18px">' + r.emoji + '</span></div>';
  }).join(''));
};
window.__wrOpenMsgReactPicker = function (messageId) {
  var m = findChatMessage1526(messageId);
  if (!m) return;
  var my = C.myMsgReaction(m, state.me);
  showDialog('Reaccionar', '<div style="display:flex;gap:8px;justify-content:center;padding:8px">' +
    C.MSG_REACTION_EMOJIS.map(function (e) {
      return '<button style="font-size:28px;background:' + (my === e ? 'rgba(224,20,48,.4)' : 'transparent') + ';border:1px solid rgba(255,255,255,.2);border-radius:50%;width:48px;height:48px" onclick="window.__wrReactToMessage(\'' + messageId + '\',\'' + e + '\')">' + e + '</button>'; /* Web 1.8: el diálogo se cierra dentro de __wrReactToMessage; antes el botón llamaba a hideDialog() suelto, que NO es global (app.js vive en un IIFE) y el diálogo nunca se cerraba. */
    }).join('') + '</div>');
};
function findChatMessage1526(messageId) {
  var found = null;
  Object.keys(state.conversations || {}).forEach(function (k) {
    var conv = state.conversations[k];
    ((conv && conv.messages) || []).forEach(function (m) { if (m.id === messageId) found = m; });
  });
  (state.groupChats || []).forEach(function (g) {
    (g.messages || []).forEach(function (m) { if (m.id === messageId) found = m; });
  });
  return found;
}

/* ---- 55. Ubicación en vivo ---- */
function liveLocationHtml1526(m) {
  if (!m.liveLocation) return '';
  var ll = m.liveLocation;
  var active = C.liveLocationActive(ll);
  var remaining = active ? Math.ceil((ll.expiresAt - Date.now()) / 60000) : 0;
  return '<div style="margin-top:4px"><img src="' + esc(C.staticMapUrl(ll.lat, ll.lng)) + '" style="width:100%;border-radius:10px" alt="Ubicación">' +
    '<p class="tiny" style="margin-top:4px">' + (active ? ' Ubicación en vivo · ' + remaining + ' min restantes' : ' Última ubicación (la ubicación en vivo ya terminó)') + ' · <span onclick="window.__wrOpenUrl(\'' + encodeURIComponent(C.osmUrl(ll.lat, ll.lng)) + '\')" style="color:var(--red);cursor:pointer">Ver en el mapa</span></p></div>';
}
window.__wrShareLiveLocation = function () {
  var phone = openChatPhone;
  var groupId = openChatGroupId;
  if (!phone && !groupId) { toast('Abre un chat primero.'); return; }
  if (!navigator.geolocation) { toast('Este teléfono no da ubicación.'); return; }
  navigator.geolocation.getCurrentPosition(function (pos) {
    var ll = { lat: pos.coords.latitude, lng: pos.coords.longitude, expiresAt: Date.now() + 3600000 };
    var r = phone
      ? C.sendMessage(state, state.me, phone, ' Ubicación en vivo (1 hora)', '', '', null, null, { liveLocation: ll })
      : C.sendGroupMessage(state, state.me, groupId, ' Ubicación en vivo (1 hora)', '', '', { liveLocation: ll });
    if (!r.ok) { toast(r.error); return; }
    save();
    if (phone) pushMessageToServer(r.message, phone); else pushGroupMessageToServer(groupId, r.message);
    liveLocationShare = { messageId: r.message.id, phone: phone, groupId: groupId || null, lat: ll.lat, lng: ll.lng, expiresAt: ll.expiresAt };
    startLiveLocationTimer1526();
    renderChatMsgs();
    renderChatHeader1526();
    toast('Compartiendo tu ubicación en vivo por 1 hora.');
  }, function () {
    toast('No se pudo obtener tu ubicación. Revisa el permiso de ubicación.');
  }, { enableHighAccuracy: true, timeout: 10000 });
};
function startLiveLocationTimer1526() {
  if (liveLocationTimer) clearInterval(liveLocationTimer);
  liveLocationTimer = setInterval(function () {
    if (!liveLocationShare) { clearInterval(liveLocationTimer); liveLocationTimer = null; return; }
    if (Date.now() > liveLocationShare.expiresAt) { stopLiveLocation1526(); return; }
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(function (pos) {
      if (!liveLocationShare) return;
      liveLocationShare.lat = pos.coords.latitude;
      liveLocationShare.lng = pos.coords.longitude;
      var m = findChatMessage1526(liveLocationShare.messageId);
      if (m && m.liveLocation) { m.liveLocation.lat = pos.coords.latitude; m.liveLocation.lng = pos.coords.longitude; save(); }
      pushToServer('/api/messages/' + encodeURIComponent(liveLocationShare.messageId) + '/location', 'POST', { lat: pos.coords.latitude, lng: pos.coords.longitude }).catch(function () {});
    }, function () {}, { enableHighAccuracy: true, timeout: 10000 });
    renderChatHeader1526();
  }, 60000);
}
window.__wrStopLiveLocation = function () { stopLiveLocation1526(); };
function stopLiveLocation1526() {
  liveLocationShare = null;
  if (liveLocationTimer) { clearInterval(liveLocationTimer); liveLocationTimer = null; }
  renderChatHeader1526();
  toast('Dejaste de compartir tu ubicación en vivo.');
}

