/* ---- 37. Fondo de chats ---- */
function applyChatBg1526() {
  var bg = state.settings && state.settings.chatBg;
  var el = $('chatMsgs');
  if (!el) return;
  if (!bg) { el.style.background = ''; return; }
  /* Longhands (no el shorthand + backgroundSize): en jsdom, poner
     backgroundSize después del shorthand hace que style.background se lea
     vacío aunque el fondo sí quede aplicado; con longhands se lee bien. */
  if (bg.indexOf('#') === 0) {
    el.style.backgroundImage = 'linear-gradient(rgba(0,0,0,.45),rgba(0,0,0,.45))';
    el.style.backgroundColor = bg;
    el.style.backgroundSize = 'cover';
  } else if (bg.indexOf('http') === 0 || bg.indexOf('data:') === 0 || bg.indexOf('content:') === 0 || bg.indexOf('file:') === 0) {
    el.style.backgroundImage = 'linear-gradient(rgba(0,0,0,.45),rgba(0,0,0,.45)),url(' + bg + ')';
    el.style.backgroundSize = 'cover';
    el.style.backgroundPosition = 'center';
  }
}
function openChatBg1526() {
  $('chatBgBody').innerHTML = '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">' +
    C.CHAT_BG_COLORS.map(function (c) {
      return '<button style="height:56px;border-radius:10px;border:2px solid ' + (state.settings.chatBg === c ? 'var(--red)' : 'rgba(255,255,255,.2)') + ';background:' + c + '" onclick="window.__wrSetChatBg(\'' + c + '\')"></button>';
    }).join('') + '</div>' +
    '<div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap"><button class="btn ghost" onclick="window.__wrPickChatBgPhoto()"> Foto de la galería</button><button class="btn ghost" onclick="window.__wrSetChatBg(\'\')">Sin fondo</button></div>' +
    '<p class="tiny muted" style="margin-top:8px">El fondo solo se ve en este teléfono.</p>';
  showOverlay('chatBgOverlay');
}
window.__wrOpenChatBg = function () { openChatBg1526(); };
window.__wrSetChatBg = function (bg) {
  if (bg && !C.chatBgValid(bg)) return;
  state.settings.chatBg = bg || '';
  save();
  applyChatBg1526();
  openChatBg1526();
  toast(bg ? 'Fondo de chats cambiado.' : 'Fondo quitado.');
};
window.__wrPickChatBgPhoto = function () {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.onchange = function () {
    var f = input.files && input.files[0];
    if (!f) return;
    var rd = new FileReader();
    rd.onload = function (e) {
      state.settings.chatBg = e.target.result;
      save();
      applyChatBg1526();
      openChatBg1526();
      toast('Fondo de chats cambiado.');
    };
    rd.readAsDataURL(f);
  };
  input.click();
};

/* ---- 54. Fijar un chat ---- */
function pinnedChats1526() {
  var list = state.pinnedChats || [];
  return list.slice().sort(function (a, b) { return (b.pinnedAt || 0) - (a.pinnedAt || 0); });
}
function isChatPinned1526(key) {
  return (state.pinnedChats || []).some(function (p) { return p.key === key; });
}
window.__wrTogglePinChat = function (key) {
  if (isChatPinned1526(key)) {
    state.pinnedChats = (state.pinnedChats || []).filter(function (p) { return p.key !== key; });
    toast('Chat quitado de fijados.');
  } else {
    state.pinnedChats = (state.pinnedChats || []).concat([{ key: key, pinnedAt: Date.now() }]);
    toast('Chat fijado arriba.');
  }
  save();
  renderConvos();
};

