/* ---- 66. Añadir un evento a tu calendario ---- */
window.__wrAddEventToCalendar = function (eventId) {
  var ev = state.events.filter(function (e) { return e.id === eventId; })[0];
  if (!ev) return;
  var startMs = C.eventStartMs(ev);
  var endMs = ev.endAt || (startMs + 3600000);
  var place = ev.place && ev.place.name ? ev.place.name : (ev.location || '');
  if (window.AndroidBridge && AndroidBridge.addToCalendar) {
    try { AndroidBridge.addToCalendar(ev.name, startMs, endMs, place, ev.description || ''); } catch (e) {}
    toast('Abriendo tu calendario con el evento ya llenado. Confírmalo ahí.');
  } else {
    toast('Tu teléfono no permite abrir el calendario desde WordRed.');
  }
};

