function profilePhotoOptionsHtml1526() {
  var p = myProfile();
  if (!p) return '';
  var frame = p.avatarFrame || 'none';
  var filter = p.avatarFilter || 'Original';
  return '<div class="glass card" style="display:block;margin-top:10px"><b>Foto de perfil</b>' +
    '<p class="tiny muted">Marco</p><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:4px">' +
    C.AVATAR_FRAMES.map(function (f) {
      return '<button class="btn ' + (frame === f ? '' : 'ghost') + ' small" onclick="window.__wrSetAvatarFrame(\'' + f + '\')">' + (f === 'none' ? 'Sin marco' : f) + '</button>';
    }).join('') + '</div>' +
    '<p class="tiny muted" style="margin-top:8px">Filtro</p><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:4px">' +
    C.AVATAR_FILTERS.map(function (f) {
      return '<button class="btn ' + (filter === f ? '' : 'ghost') + ' small" onclick="window.__wrSetAvatarFilter(\'' + f + '\')">' + f + '</button>';
    }).join('') + '</div>' +
    '<div style="margin-top:10px"><button class="btn ghost small" onclick="window.__wrUploadAvatarVideo()"> Usar un video corto como foto de perfil (máx. 6 s)</button></div>' +
    (p.avatarVideo ? '<p class="tiny" style="margin-top:6px">Video activo en tu perfil. <button class="tiny" onclick="window.__wrClearAvatarVideo()">Quitar video</button></p>' : '') +
    '</div>';
}
window.__wrSetAvatarFrame = async function (frame) {
  frame = C.validateAvatarFrame(frame);
  var p = myProfile();
  if (!p) return;
  p.avatarFrame = frame;
  save();
  await pushToServer('/api/profile', 'POST', { avatarFrame: frame });
  pushProfileToServer();
  renderOwnProfile();
};
window.__wrSetAvatarFilter = async function (filter) {
  filter = C.validateAvatarFilter(filter);
  var p = myProfile();
  if (!p) return;
  p.avatarFilter = filter;
  save();
  await pushToServer('/api/profile', 'POST', { avatarFilter: filter });
  pushProfileToServer();
  renderOwnProfile();
};
window.__wrUploadAvatarVideo = function () {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = 'video/*';
  input.onchange = async function () {
    var f = input.files && input.files[0];
    if (!f) return;
    var video = document.createElement('video');
    video.preload = 'metadata';
    video.onloadedmetadata = async function () {
      var durationMs = Math.round(video.duration * 1000);
      if (durationMs > 6000) { toast('El video debe durar 6 segundos o menos.'); return; }
      uploadAvatarVideo1526(f, durationMs);
    };
    video.onerror = function () { toast('No se pudo leer ese video.'); };
    video.src = URL.createObjectURL(f);
  };
  input.click();
};
async function uploadAvatarVideo1526(file, durationMs) {
  showUploadProgress(10, 'Subiendo el video…');
  var url = null;
  try { url = await uploadFileToServer(file, function (p) { showUploadProgress(p, 'Subiendo el video…'); }); } catch (e) { url = null; }
  hideUploadProgress();
  if (!url) { toast('No se pudo subir el video.'); return; }
  var v = C.validateAvatarVideo({ url: url, durationMs: durationMs });
  if (!v) { toast('El video debe durar 6 segundos o menos.'); return; }
  var r = await pushToServer('/api/profile', 'POST', { avatarVideo: v });
  if (!r.ok) { toast(r.error || 'No se pudo guardar el video.'); return; }
  var p = myProfile();
  if (p) p.avatarVideo = v;
  save();
  pushProfileToServer();
  renderOwnProfile();
  toast('Video de perfil guardado.');
}
window.__wrClearAvatarVideo = async function () {
  var p = myProfile();
  if (!p) return;
  p.avatarVideo = null;
  save();
  await pushToServer('/api/profile', 'POST', { avatarVideo: null });
  pushProfileToServer();
  renderOwnProfile();
};
function bindProfilePhotoOptions1526() {
  var el = $('profilePhotoOptions');
  if (!el) return;
  el.innerHTML = profilePhotoOptionsHtml1526();
}

