/* ---- mensajes del servidor 1.5.26 (regalos, invitados, salas) ---- */
function handleServerMessage1526(data) {
  if (!data || !data.kind) return false;
  if (data.kind === 'liveGift') {
    if (currentLive && data.liveId === currentLive.id) {
      renderLiveGiftCounts1526(data.counts, data.total);
      spawnLiveGiftAnim1526(data.giftId);
    }
    return true;
  }
  if (data.kind === 'liveInvite') {
    if (data.to === state.me || data.phone === state.me) {
      liveInvitePending = { liveId: data.liveId, from: data.from };
      var item = C.notify(state, { type: 'liveInvite', from: data.from, to: state.me, text: 'te invitó a su en vivo como invitado', refId: data.liveId });
      if (item) { save(); updateBadges(); }
      toast(profileName(data.from) + ' te invitó a su en vivo. Toca la campana para aceptar o rechazar.');
    }
    return true;
  }
  if (data.kind === 'liveInviteAccepted') {
    if (currentLive && data.liveId === currentLive.id) {
      currentLive.coHost = data.phone || data.coHost || null;
      toast(profileName(data.phone || '') + ' aceptó y se unió al live.');
      showLiveOverlay();
    }
    return true;
  }
  if (data.kind === 'liveInviteDeclined') {
    if (currentLive && data.liveId === currentLive.id) toast(profileName(data.phone || '') + ' rechazó la invitación.');
    return true;
  }
  if (data.kind === 'liveCoHostLeft') {
    if (currentLive && data.liveId === currentLive.id) {
      removeCoHostFromViewers1526(); /* 1.5.26 (23): quitar su video de los espectadores */
      currentLive.coHost = null;
      liveInvitedCoHost = null;
      stopCoHostPublish1526();
      toast('El invitado salió del live. El live sigue solo contigo.');
      showLiveOverlay();
    }
    return true;
  }
  if (data.kind === 'audioRoomUpdated') {
    if (data.room) {
      var idx = -1;
      audioRoomsCache.forEach(function (rm, i) { if (rm.id === data.room.id) idx = i; });
      if (idx >= 0) audioRoomsCache[idx] = data.room;
      else audioRoomsCache.push(data.room);
      if (audioRoom && audioRoom.id === data.room.id) { audioRoom = data.room; openAudioRoomView1526(); }
    }
    return true;
  }
  if (data.kind === 'audioRoomClosed') {
    audioRoomsCache = audioRoomsCache.filter(function (rm) { return rm.id !== data.roomId; });
    if (audioRoom && audioRoom.id === data.roomId) {
      leaveAudioRoomLocal1526();
      toast('La sala de audio se cerró.');
    }
    return true;
  }
  if (data.kind === 'audioRoomSignal') {
    handleAudioRoomSignal1526(data);
    return true;
  }
  if (data.kind === 'mention') {
    var item2 = C.notify(state, { type: 'mention', from: data.from, to: state.me, text: 'te mencionó en un comentario', refId: data.postId, commentId: data.commentId });
    if (item2) { save(); updateBadges(); }
    return true;
  }
  return false;
}
async function handleAudioRoomSignal1526(data) {
  /* Malla de voz: la señal llega por el servidor 3.8
     (POST /api/audio-rooms/:id/signal → 'audioRoomSignal'). El que
     entra ofrece a los que ya están (startAudioRoomOffers1526) y los
     demás responden aquí. */
  if (!audioRoom || !audioRoomStream) return;
  try {
    var from = data.from;
    var pc = audioRoomPcs[from];
    if (data.type === 'offer' && !pc) {
      pc = makePeerConnection();
      audioRoomPcs[from] = pc;
      audioRoomStream.getTracks().forEach(function (t) { pc.addTrack(t, audioRoomStream); });
      pc.ontrack = function (ev) {
        var a = document.createElement('audio');
        a.srcObject = ev.streams[0];
        a.autoplay = true;
        a.playsInline = true;
        document.body.appendChild(a);
      };
      pc.onicecandidate = function (ev) {
        if (ev.candidate) pushToServer('/api/audio-rooms/' + encodeURIComponent(audioRoom.id) + '/signal', 'POST', { to: from, type: 'ice', candidate: ev.candidate });
      };
      await pc.setRemoteDescription(new RTCSessionDescription(data.offer || data.payload));
      var ans = await pc.createAnswer();
      await pc.setLocalDescription(ans);
      pushToServer('/api/audio-rooms/' + encodeURIComponent(audioRoom.id) + '/signal', 'POST', { to: from, type: 'answer', answer: ans });
    } else if (data.type === 'answer' && pc) {
      await pc.setRemoteDescription(new RTCSessionDescription(data.answer || data.payload));
    } else if (data.type === 'ice' && pc) {
      try { await pc.addIceCandidate(new RTCIceCandidate(data.candidate || data.payload)); } catch (e) {}
    }
  } catch (e) {}
}

/* ---- 17/7/29/13/39/50. Campos nuevos del creador de historias ---- */
function renderStoryCreate1526() {
  var box = $('storyCreate1526');
  if (!box) return;
  var friends = (state.friends[state.me] || []).length;
  box.innerHTML =
    '<div style="margin-top:10px"><label class="tiny">Encuesta (pregunta + 2 opciones)</label>' +
    '<input id="storyPollQ" type="text" maxlength="200" placeholder="Pregunta de la encuesta" value="' + esc(storyPollQ) + '" style="margin-top:6px">' +
    '<div style="display:flex;gap:8px;margin-top:6px"><input id="storyPollOpt0" type="text" maxlength="80" placeholder="Opción 1" value="' + esc(storyPollOpts[0]) + '" style="flex:1"><input id="storyPollOpt1" type="text" maxlength="80" placeholder="Opción 2" value="' + esc(storyPollOpts[1]) + '" style="flex:1"></div></div>' +
    '<div style="margin-top:10px"><label class="tiny">Enlace (opcional)</label><input id="storyLinkInput" type="url" inputmode="url" placeholder="https://..." value="' + esc(storyLink) + '" style="margin-top:6px"></div>' +
    '<div style="margin-top:10px"><label class="tiny">¿Quién puede verla?</label><select id="storyAudienceSelect" style="margin-top:6px"><option value="all">Todos</option><option value="close"' + (storyAudience === 'close' ? ' selected' : '') + '>Solo cercanos (' + friends + ')</option></select></div>' +
    '<div style="margin-top:10px"><label class="tiny">Solo texto: fondo de color</label><div class="chiprow" style="margin-top:6px">' +
    [''].concat(C.STORY_TEXT_BG_COLORS).map(function (c) {
      return '<button type="button" class="chip' + (storyBgColor === c ? ' on' : '') + '" data-storybg="' + c + '" style="' + (c ? 'background:' + c + ';color:#fff' : '') + '">' + (c ? '■' : 'Sin fondo') + '</button>';
    }).join('') + '</div></div>' +
    '<div style="margin-top:10px"><label class="tiny">Nota de voz (opcional)</label>' +
    '<div style="display:flex;gap:8px;margin-top:6px;align-items:center"><button type="button" class="btn ghost small" id="storyVoiceBtn">' + (storyVoice ? ' Nota grabada (' + Math.round((storyVoice.durationMs || 0) / 1000) + ' s) · Cambiar' : ' Grabar nota de voz') + '</button>' +
    (storyVoice ? '<button type="button" class="btn ghost small" id="storyVoiceClear">Quitar</button>' : '') + '</div>' +
    '<div style="display:flex;gap:8px;margin-top:6px;align-items:center"><span class="tiny">Portada:</span><input type="color" id="storyCoverColor" value="' + esc(storyCover && storyCover.indexOf('#') === 0 ? storyCover : '#e01430') + '" style="width:52px;height:32px;padding:2px"><button type="button" class="btn ghost small" id="storyCoverPickBtn">Foto de portada</button></div></div>';
  box.querySelectorAll('[data-storybg]').forEach(function (b) {
    b.addEventListener('click', function () { storyBgColor = b.getAttribute('data-storybg'); renderStoryCreate1526(); });
  });
  var q = $('storyPollQ');
  if (q) q.addEventListener('input', function () { storyPollQ = q.value; });
  var o0 = $('storyPollOpt0');
  if (o0) o0.addEventListener('input', function () { storyPollOpts[0] = o0.value; });
  var o1 = $('storyPollOpt1');
  if (o1) o1.addEventListener('input', function () { storyPollOpts[1] = o1.value; });
  var li = $('storyLinkInput');
  if (li) li.addEventListener('input', function () { storyLink = li.value; });
  var au = $('storyAudienceSelect');
  if (au) au.addEventListener('change', function () { storyAudience = au.value; });
  var vb = $('storyVoiceBtn');
  if (vb) vb.addEventListener('click', function () {
    /* La barra de grabación vive en la vista de chat, que aquí no se ve:
       el propio botón empieza y detiene la grabación. */
    if (voiceRec.active && voiceRecForStory) { stopVoiceRecord(true); return; }
    voiceRecForStory = true;
    startVoiceRecord();
    vb.textContent = '■ Detener grabación';
    toast('Grabando tu nota de voz para la historia… Toca de nuevo para detener.');
  });
  var vc = $('storyVoiceClear');
  if (vc) vc.addEventListener('click', function () { storyVoice = null; storyCover = ''; renderStoryCreate1526(); });
  var cc = $('storyCoverColor');
  if (cc) cc.addEventListener('input', function () { storyCover = cc.value; });
  var cp = $('storyCoverPickBtn');
  if (cp) cp.addEventListener('click', function () { $('storyCoverInput').click(); });
}
function storyVoiceFromChat1526(uri, durationMs) {
  storyVoice = { uri: uri, durationMs: durationMs || 0 };
  renderStoryCreate1526();
  toast('Nota de voz lista para tu historia.');
}

