$('liveStartBtn').addEventListener('click', startLive);
$('liveChatSend').addEventListener('click', sendLiveChat);
$('liveChatInput').addEventListener('keydown', function (e) { if (e.key === 'Enter') sendLiveChat(); });
$('liveLeaveBtn').addEventListener('click', function () { leaveLive(); });
$('liveEndBtn').addEventListener('click', function () { endLive(); });
$('liveLikeBtn').addEventListener('click', function () { sendLiveLike(); });
$('liveShareBtn').addEventListener('click', function () { window.__wrShareLive(); });
$('liveCloseBtn').addEventListener('click', function () { leaveLive(); });
/* v1.7: controles del transmisor en el live (cámara, zoom, filtros,
   pantalla, grabación) + pellizco para el zoom sobre el video. */
$('liveCamBtn').addEventListener('click', function () { switchLiveCamera(); });
$('liveZoomInBtn').addEventListener('click', function () { liveZoomIn(); });
$('liveZoomOutBtn').addEventListener('click', function () { liveZoomOut(); });
